template.css:
.sc-eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted-foreground); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.85rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.75rem; margin: 0.25rem 0 0; }

.co-target { text-align: center; margin: -0.25rem 0 -0.5rem; }
.co-hex { font: 600 2.2rem var(--font-mono); letter-spacing: 0.04em; }
.co-swatches { display: grid; grid-template-columns: 1fr; gap: 0.6rem; max-width: 30rem; width: 100%; margin: 0 auto; }
.co-swatches.both { grid-template-columns: 1fr 1fr; }
.co-swatch { position: relative; height: 8rem; border-radius: var(--radius); border: 1px solid var(--border); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--foreground) 6%, transparent); transition: background 0.05s; }
.co-cap { position: absolute; left: 0.5rem; bottom: 0.5rem; font: 500 0.75rem var(--font-mono); padding: 0.15rem 0.45rem; border-radius: 0.4rem; background: color-mix(in oklab, var(--background, #000) 75%, transparent); color: var(--foreground); }

.co-sliders { display: flex; flex-direction: column; gap: 0.9rem; max-width: 30rem; width: 100%; margin: 0 auto; }
.co-slider { position: relative; display: flex; flex-direction: column; gap: 0.35rem; }
.co-name { font-size: 0.8rem; color: var(--muted-foreground); }
.co-slider input { -webkit-appearance: none; appearance: none; width: 100%; height: 2.75rem; margin: 0; background: transparent; cursor: pointer; touch-action: pan-y; }
.co-slider input:disabled { cursor: default; }
.co-slider input::-webkit-slider-runnable-track { height: 1.1rem; border-radius: 999px; background: var(--track); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--foreground) 12%, transparent); }
.co-slider input::-moz-range-track { height: 1.1rem; border-radius: 999px; background: var(--track); }
.co-slider input::-webkit-slider-thumb { -webkit-appearance: none; width: 1.4rem; height: 1.4rem; margin-top: -0.15rem; border-radius: 50%; background: var(--thumb); border: 3px solid var(--foreground); box-shadow: 0 1px 4px rgb(0 0 0 / 35%); }
.co-slider input::-moz-range-thumb { width: 1.4rem; height: 1.4rem; border-radius: 50%; background: var(--thumb); border: 3px solid var(--foreground); box-sizing: border-box; }
.co-slider input:focus-visible { outline: none; }
.co-slider input:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 4px color-mix(in oklab, var(--ring) 45%, transparent); }
.co-tick { position: absolute; bottom: 0.35rem; width: 3px; height: 2rem; margin-left: -1.5px; border-radius: 2px; background: var(--foreground); box-shadow: 0 0 0 1.5px var(--background, #000); pointer-events: none; }
.co-tick::after { content: "target"; position: absolute; top: -1.15rem; left: 50%; transform: translateX(-50%); font-size: 0.65rem; color: var(--muted-foreground); }
.co-hint { font-size: 0.85rem; text-align: center; margin-top: -0.4rem; }
.co-hint code { font: 0.85em var(--font-mono); background: var(--muted); padding: 0.05em 0.3em; border-radius: 0.3em; }

.co-verdict { display: flex; flex-direction: column; gap: 0.15rem; }
.co-big { font-size: 1.35rem; font-weight: 600; }
.co-big.good { color: var(--success); }
.co-big.near { color: var(--warning); }
.co-big.far { color: var(--danger); }
.co-compare table { margin: 0 0 0.5rem; }
.co-compare:empty { display: none; }

/* Etude 3 look: a quiet grey eyebrow and the question in the study serif, as in the Design Lab. */
.sc-eyebrow + .prose, .sc-eyebrow + .uc-prompt .uc-ask, .sc-eyebrow + .bt-ask, .sp-title, .wk-prompt, .cm-ask { font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; font-size: 1.5rem; line-height: 1.3; letter-spacing: -0.005em; }
.sc-eyebrow + .prose code, .wk-prompt code { font-size: 0.8em; }

template.js:
const sliders = Object.fromEntries(etude.$$(".co-slider").map((el) => [el.dataset.k, el.querySelector("input")]));
const mine = etude.$(".co-swatch.mine");
const start = etude.answer && [etude.answer.h, etude.answer.s, etude.answer.l].every(Number.isFinite) ? etude.answer : { h: 180, s: 0, l: 50 };
sliders.h.value = start.h;
sliders.s.value = start.s;
sliders.l.value = start.l;
let touched = !!etude.answer;

const val = () => ({ h: Number(sliders.h.value), s: Number(sliders.s.value), l: Number(sliders.l.value) });
const css = ({ h, s, l }) => `hsl(${h} ${s}% ${l}%)`;
// Track gradients show where each slider would take the color, given the other two.
const paint = () => {
  const v = val();
  mine.style.background = css(v);
  const hues = [0, 60, 120, 180, 240, 300, 360].map((h) => css({ h, s: Math.max(v.s, 25), l: Math.min(Math.max(v.l, 30), 70) })).join(", ");
  sliders.h.style.setProperty("--track", `linear-gradient(90deg, ${hues})`);
  sliders.s.style.setProperty("--track", `linear-gradient(90deg, ${css({ ...v, s: 0 })}, ${css({ ...v, s: 100 })})`);
  sliders.l.style.setProperty("--track", `linear-gradient(90deg, #000, ${css({ ...v, l: 50 })}, #fff)`);
  for (const [k, el] of Object.entries(sliders)) el.style.setProperty("--thumb", css(v));
};
for (const el of Object.values(sliders)) {
  el.addEventListener("input", () => {
    touched = true;
    paint();
    etude.setReady(true);
  });
  el.addEventListener("keydown", (e) => {
    if (!e.shiftKey || !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(e.key)) return;
    e.preventDefault();
    const d = e.key === "ArrowRight" || e.key === "ArrowUp" ? 10 : -10;
    el.value = String(Math.max(Number(el.min), Math.min(Number(el.max), Number(el.value) + d)));
    el.dispatchEvent(new Event("input"));
  });
}
paint();
etude.setReady(touched);
etude.getAnswer(() => val());

function hslToRgb(h, s, l) {
  s /= 100; l /= 100;
  const k = (n) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n) => l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
  return [f(0), f(8), f(4)].map((v) => Math.round(v * 255));
}
const hex = (rgb) => "#" + rgb.map((v) => v.toString(16).padStart(2, "0")).join("").toUpperCase();

etude.onResult(({ grade, key, answer }) => {
  const a = answer && Number.isFinite(answer.h) ? answer : val();
  sliders.h.value = a.h; sliders.s.value = a.s; sliders.l.value = a.l;
  paint();
  for (const el of Object.values(sliders)) el.disabled = true;
  const [th, ts, tl] = key.hsl;
  const target = etude.$(".co-swatch.target");
  target.style.background = `rgb(${key.rgb.join(" ")})`;
  etude.$(".co-swatches").classList.add("both");
  const preview = document.body.dataset.preview === "1";
  const myHex = hex(hslToRgb(a.h, a.s, a.l));

  // Target positions on each slider, as small ticks.
  for (const [k, v, max] of [["h", th, 359], ["s", ts, 100], ["l", tl, 100]]) {
    const wrap = etude.$(`.co-slider[data-k="${k}"]`);
    const tick = document.createElement("i");
    tick.className = "co-tick";
    tick.style.left = `calc(${(v / max) * 100}% + ${(0.5 - v / max) * 1.4}rem)`;
    wrap.querySelector("input").after(tick);
  }

  if (preview) {
    mine.style.background = `rgb(${key.rgb.join(" ")})`;
    mine.querySelector(".co-cap").textContent = "Target";
    target.remove();
    etude.$(".co-swatches").classList.remove("both");
  } else mine.querySelector(".co-cap").textContent = "Yours · " + myHex;

  const d = grade?.details ?? {};
  const v = etude.$(".co-verdict");
  if (preview) v.innerHTML = etude.md(`$\\mathrm{hsl}(${th}^\\circ,\\ ${ts}\\%,\\ ${tl}\\%)$`);
  else {
    const tone = grade.score >= 1 ? "good" : grade.score > 0 ? "near" : "far";
    const words = d.notes?.length ? d.notes.join(", ") : grade.score >= 1 ? "nothing a quick glance would notice" : "";
    v.innerHTML = `<div class="co-big ${tone}">${etude.escape(d.verdict ?? "")}</div><div class="e-muted">${etude.escape(words.charAt(0).toUpperCase() + words.slice(1))}${words ? "." : ""}</div>`;
    etude.$(".co-compare").innerHTML = etude.md(
      `| | hue | saturation | lightness |\n|---|---|---|---|\n| target | $${th}^\\circ$ | $${ts}\\%$ | $${tl}\\%$ |\n| yours | $${a.h}^\\circ$ | $${a.s}\\%$ | $${a.l}\\%$ |\n\nDistance in OKLab: $\\Delta E = ${d.dE}$ (full credit up to $0.05$, nothing past $0.22$).`,
    );
    etude.$(".co-compare").classList.add("prose");
  }
});

