const said = norm(answer);
const mine = KEYS[key.index];
if (!said) return { score: 0, feedback: "No answer." };
if ((ACCEPT[mine] ?? []).includes(said)) {
  const note = NOTES[mine]?.[said];
  return { score: 1, feedback: note };
}
// Exactly another country's name: wrong, and show where that one is.
for (const [k, list] of Object.entries(ACCEPT)) {
  if (k !== mine && list.includes(said)) {
    const i = KEYS.indexOf(k);
    const near = (NEIGH[key.index] ?? []).includes(i);
    return { score: 0, feedback: near ? `${The(NAMES[i])} is its neighbour. This is ${the(key.country)}.` : `${The(NAMES[i])} is a different country. This is ${the(key.country)}.`, details: { otherIndex: i, otherName: NAMES[i] } };
  }
}
// A typo: close to this country's name and closer to it than to any other country's.
const allow = said.length >= 9 ? 2 : said.length >= 5 ? 1 : 0;
if (allow) {
  let bestMine = allow + 1, bestOther = allow + 1;
  for (const a of ACCEPT[mine] ?? []) bestMine = Math.min(bestMine, dist(said, a, allow));
  if (bestMine <= allow) {
    for (const [k, list] of Object.entries(ACCEPT)) {
      if (k === mine) continue;
      for (const a of list) bestOther = Math.min(bestOther, dist(said, a, bestMine));
    }
    if (bestOther > bestMine) return { score: 0.9, feedback: `Close enough: it's spelled ${key.country}.` };
  }
}
return { score: 0, feedback: `This is ${the(key.country)}.` };

template.css:
.cm-head { display: flex; flex-direction: column; gap: 0.35rem; margin-bottom: -0.4rem; }
.cm-eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted-foreground); }
.cm-ask { font-size: 1.9rem; font-weight: 600; letter-spacing: -0.01em; line-height: 1.15; }

.cm-stage { position: relative; border-radius: var(--radius); overflow: hidden; border: 1px solid var(--border); }
.cm-svg { display: block; width: 100%; height: 360px; touch-action: none; user-select: none; -webkit-user-select: none; cursor: grab; }
.cm-svg.panning { cursor: grabbing; }
.cm-svg.done { cursor: default; }
.cm-svg:focus { outline: none; }
.cm-sea { fill: color-mix(in oklab, var(--foreground) 3%, var(--card, var(--background))); }

.cm-land path { fill: color-mix(in oklab, var(--foreground) 17%, var(--card, var(--background))); stroke: var(--card, var(--background)); stroke-width: 0.7px; vector-effect: non-scaling-stroke; stroke-linejoin: round; transition: fill 0.12s; }
.cm-land path.other { fill: color-mix(in oklab, var(--foreground) 11%, var(--card, var(--background))); }
:is([data-face="locate"], [data-face="capital-of"]) .cm-svg:not(.done) .cm-land path:not(.other):not(.picked):hover { fill: color-mix(in oklab, var(--foreground) 30%, var(--card, var(--background))); }
.cm-land path.target { fill: var(--highlight); stroke: color-mix(in oklab, var(--highlight) 60%, var(--foreground)); stroke-width: 1px; }
.cm-land path.picked { fill: var(--highlight); stroke: var(--foreground); stroke-width: 1.2px; }
.cm-land path.right, .cm-land path.answer { fill: var(--success); stroke: color-mix(in oklab, var(--success) 50%, var(--foreground)); stroke-width: 1.2px; }
.cm-land path.wrong { fill: var(--danger); stroke: color-mix(in oklab, var(--danger) 50%, var(--foreground)); stroke-width: 1.2px; }

.cm-dots .dot { fill: color-mix(in oklab, var(--foreground) 32%, transparent); stroke: var(--card, var(--background)); stroke-width: 1px; vector-effect: non-scaling-stroke; }
.cm-dots .dot.hot { fill: var(--highlight); stroke: var(--foreground); }
.cm-dots .dot.right, .cm-dots .dot.answer { fill: var(--success); }
.cm-dots .dot.wrong { fill: var(--danger); }
.cm-marks .ring { fill: none; stroke: var(--highlight); stroke-width: 1.6px; vector-effect: non-scaling-stroke; stroke-dasharray: 3 3; }
[data-mode="result"] .cm-marks .ring { stroke: var(--success); stroke-dasharray: none; stroke-width: 2px; }
[data-mode="result"] .cm-marks .ring.wrong { stroke: var(--danger); }
.cm-marks .lbl { font-family: var(--font-sans); font-weight: 600; fill: var(--foreground); paint-order: stroke; stroke: color-mix(in oklab, var(--card, var(--background)) 92%, transparent); stroke-width: 4px; vector-effect: non-scaling-stroke; stroke-linejoin: round; pointer-events: none; }
.cm-marks .lbl.wrong { font-weight: 500; }

.cm-zoom { position: absolute; right: 0.5rem; top: 0.5rem; display: flex; flex-direction: column; gap: 0.3rem; }
.cm-zoom button { width: 2.25rem; height: 2.25rem; border-radius: calc(var(--radius) - 2px); border: 1px solid var(--border); background: color-mix(in oklab, var(--card, var(--background)) 88%, transparent); color: var(--foreground); font: 600 1rem/1 var(--font-sans); cursor: pointer; display: grid; place-items: center; padding: 0; }
.cm-zoom button:hover { background: var(--secondary); }
.cm-zoom button:focus { outline: none; }
.cm-zoom button:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; }

.cm-input { font-size: 1.1rem; }
.cm-input.is-close { border-color: var(--warning); }
.cm-status { margin: -0.5rem 0 0; font-size: 0.95rem; color: var(--muted-foreground); }
.cm-hint { margin: -0.7rem 0 0; font-size: 0.8rem; color: var(--muted-foreground); }
.cm-name { font-size: 1.5rem; font-weight: 600; letter-spacing: -0.01em; }
.cm-official { color: var(--muted-foreground); margin-top: -0.6rem; }
.cm-facts { display: flex; flex-wrap: wrap; gap: 0.4rem 1.4rem; font-size: 0.95rem; }
.cm-facts .e-label { margin-right: 0.35rem; }
@media (max-width: 480px) { .cm-ask { font-size: 1.6rem; } .cm-zoom button { width: 2.75rem; height: 2.75rem; } }

[data-face="capital-of"][data-mode="answer"] .cm-hint { display: none; }

.cm-marks .cap { fill: var(--foreground); stroke: var(--card, var(--background)); stroke-width: 1.5px; vector-effect: non-scaling-stroke; pointer-events: none; }
.cm-marks .cap-label { font-weight: 500; }

/* Etude 3 look: a quiet grey eyebrow and the question in the study serif, as in the Design Lab. */
.sc-eyebrow + .prose, .sc-eyebrow + .uc-prompt .uc-ask, .sc-eyebrow + .bt-ask, .sp-title, .wk-prompt, .cm-ask { font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; font-size: 1.5rem; line-height: 1.3; letter-spacing: -0.005em; }
.sc-eyebrow + .prose code, .wk-prompt code { font-size: 0.8em; }

grader.code:
// Full credit inside the tolerance, falling linearly to zero at five times it.
const g = Number(answer);
if (!Number.isFinite(g)) return { score: 0, feedback: "No estimate given.", details: {} };
const t = key.tolerance;
let err, words;
if (view.scale === "log") {
  if (g <= 0) return { score: 0, details: { error: Infinity } };
  err = Math.abs(Math.log10(g / key.answer));
  const ratio = g > key.answer ? g / key.answer : key.answer / g;
  const r = ratio < 10 ? Math.round(ratio * 10) / 10 : Math.round(ratio);
  words = ratio < 1.05 ? "essentially exact" : `${g > key.answer ? "too high" : "too low"} by a factor of ${r}` + (err >= 1.15 ? ` (${Math.round(err * 10) / 10} ${Math.round(err * 10) === 10 ? "order" : "orders"} of magnitude)` : "");
} else {
  err = Math.abs(g - key.answer) / (view.max - view.min);
  const pct = Math.round((Math.abs(g - key.answer) / Math.abs(key.answer)) * 1000) / 10;
  words = pct < 0.5 ? "essentially exact" : `${pct}% ${g > key.answer ? "too high" : "too low"}`;
}
const zero = 5 * t;
const score = err <= t ? 1 : err >= zero ? 0 : 1 - (err - t) / (zero - t);
return { score: Math.round(score * 100) / 100, feedback: score < 1 ? words.charAt(0).toUpperCase() + words.slice(1) + "." : undefined, details: { error: err, words } };

types.prepare:
const log = fields.scale === "log";
const min = Number(fields.min), max = Number(fields.max);
if (!(max > min)) throw new Error("max must be greater than min");
if (log && !(min > 0)) throw new Error("a log scale needs min > 0");
const tol = Number.isFinite(fields.tolerance) && fields.tolerance > 0 ? fields.tolerance : log ? 0.1 : 0.04;
return {
  view: {
    prompt: fields.prompt,
    min,
    max,
    scale: log ? "log" : "linear",
    isLog: log,
    isLinear: !log,
    step: Number.isFinite(fields.step) && fields.step > 0 ? fields.step : 0,
    unit: fields.unit ?? "",
  },
  key: { answer: Number(fields.answer), tolerance: tol, explanation: fields.explanation ?? "" },
};

types.demo:
// An example answer for watch mode: a good estimate, not quite the exact value.
const a = Number(key.answer);
const off = (rng.next() * 2 - 1) * (key.tolerance ?? 0.05) * 0.4;
const g = view.scale === "log" ? a * Math.pow(10, off) : a * (1 + off);
const step = Number(view.step) || 0;
return step ? Math.round(g / step) * step : g;

