template.js:
const { view } = etude;
const BASE = Number(view.base) || 16;
const SPEED = Number(view.speed) || 1;
const HINTS = view.hints !== false;
const pop = (n) => { let c = 0; while (n) { c += n & 1; n >>= 1; } return c; };
const fmt = (v) => v.toString(BASE).toUpperCase();
const bin = (v) => { const s = v.toString(2).padStart(8, "0"); return `${s.slice(0, 4)} ${s.slice(4)}`; };
const BASE_NAME = { 2: "BIN", 8: "OCT", 10: "DEC", 16: "HEX" }[BASE] ?? `BASE ${BASE}`;

if (!etude.result) game();

function game() {
  const W = 480, H = 576;
  const GROUND = 410, TILE_Y = 458, TILE_H = 58, TW = 57, TX0 = 12;
  const EW = 56, EH = 58;
  const C = {
    bg: "#0a0f1f", star: "#8ea2e8", city: "#111a36", cityLit: "#26345f", ground: "#1c2747", groundTop: "#3ee6c1",
    tileOff: "#131a32", tileOffEdge: "#26315a", tileOffText: "#56669b", tileOn: "#ffd166", tileOnText: "#0a0f1f",
    text: "#e8ecff", dim: "#6f7db0", danger: "#ff4d6d", flame: "#ff8a3d",
    inv: ["#ff5c8a", "#6ee7f9", "#a78bfa", "#7cf29c", "#ffb36b"],
  };
  const FONT = "FlippyPixel";
  const font = (px) => `${px}px ${FONT}, ui-monospace, monospace`;

  const stage = etude.$(".fb-stage");
  const canvas = etude.$(".fb-canvas");
  const ctx = canvas.getContext("2d");
  const ff = new FontFace(FONT, "url(data:font/ttf;base64,)");
  ff.load().then((f) => document.fonts.add(f)).catch(() => {});

  // The eight bits, left to right: 128 … 1. Monkeytype-style key rows, as in the original game.
  const ROWS = ["12345678", "qwertyui", "asdfghjk", "zxcvbnm,"];
  const keyBit = {};
  ROWS.forEach((r) => Array.from(r).forEach((c, i) => { keyBit[c] = i; }));

  const SPRITES = [
    ["..X.....X..", "...X...X...", "..XXXXXXX..", ".XX.XXX.XX.", "XXXXXXXXXXX", "X.XXXXXXX.X", "X.X.....X.X", "...XX.XX..."],
    ["..X.....X..", "X..X...X..X", "X.XXXXXXX.X", "XXX.XXX.XXX", "XXXXXXXXXXX", ".XXXXXXXXX.", "..X.....X..", ".X.......X."],
  ];
  const ROCKET = [".X.", "XXX", "XXX", "XXX", "X.X"];

  const stars = Array.from({ length: 70 }, () => ({ x: Math.random() * W, y: Math.random() * (GROUND - 30), s: Math.random() < 0.2 ? 2 : 1, ph: Math.random() * 6.28 }));
  const city = [];
  for (let x = 0; x < W;) { const w = 18 + Math.floor(Math.random() * 30); city.push({ x, w, h: 14 + Math.floor(Math.random() * 46), lit: Array.from({ length: 6 }, () => Math.random() < 0.35) }); x += w + 2; }

  let phase = "title"; // title, play, paused, over, done
  let bits = 0, kills = 0, playTime = 0, spawnT = 0, lastShot = 0, flips = 0, died = null, overT = 0, shake = 0, blink = 0;
  let sound = view.sound !== false, toast = null;
  const enemies = [], rockets = [], parts = [], floats = [], tileBump = new Array(8).fill(0);
  const log = [];
  let uid = 0;

  // ---------------------------------------------------------------- sound
  let ac = null;
  const audio = () => {
    if (!sound) return null;
    try { ac ??= new AudioContext(); if (ac.state === "suspended") ac.resume(); } catch { return null; }
    return ac;
  };
  const tone = (f0, f1, dur, type = "square", vol = 0.05) => {
    const a = audio(); if (!a) return;
    const o = a.createOscillator(), g = a.createGain(), t = a.currentTime;
    o.type = type;
    o.frequency.setValueAtTime(f0, t);
    if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(f1, t + dur);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    o.connect(g).connect(a.destination);
    o.start(t); o.stop(t + dur + 0.02);
  };
  const boom = (dur = 0.35, vol = 0.12) => {
    const a = audio(); if (!a) return;
    const n = Math.floor(a.sampleRate * dur), buf = a.createBuffer(1, n, a.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n) ** 2;
    const s = a.createBufferSource(), f = a.createBiquadFilter(), g = a.createGain(), t = a.currentTime;
    s.buffer = buf; f.type = "lowpass"; f.frequency.setValueAtTime(2400, t); f.frequency.exponentialRampToValueAtTime(180, t + dur);
    g.gain.value = vol;
    s.connect(f).connect(g).connect(a.destination);
    s.start(t);
  };

  // ---------------------------------------------------------------- game rules
  const VALUES = [];
  for (let v = 3; v < 256; v++) if (v & (v - 1)) VALUES.push(v);
  const fallSpeed = () => (20 + 0.75 * kills) * SPEED;
  const interval = () => Math.max(0.9, 4.2 - 0.015 * playTime - 0.035 * kills) / SPEED;

  const spawn = () => {
    let x = 0;
    for (let k = 0; k < 10; k++) {
      x = 12 + Math.random() * (W - EW - 24);
      if (!enemies.some((e) => e.y < 130 && Math.abs(e.x - x) < EW + 10)) break;
    }
    let v = VALUES[Math.floor(Math.random() * VALUES.length)];
    if (enemies.some((e) => e.v === v && !e.locked)) v = VALUES[Math.floor(Math.random() * VALUES.length)];
    enemies.push({ id: ++uid, v, x, y: 42, born: playTime, color: C.inv[uid % C.inv.length], locked: false, ph: Math.random() });
  };

  const start = () => {
    phase = "play";
    etude.setReady(false);
    spawn();
    spawnT = interval();
    tone(330, 660, 0.12, "square", 0.04);
  };

  const flip = (i) => {
    if (phase === "title") return start();
    if (phase === "paused") { phase = "play"; return; }
    if (phase !== "play") return;
    bits ^= 1 << (7 - i);
    flips++;
    tileBump[i] = 1;
    tone(260 * 2 ** (i / 7), 260 * 2 ** (i / 7) * 1.06, 0.06, "square", 0.035);
    const hit = enemies.filter((e) => !e.locked && e.v === bits).sort((a, b) => b.y - a.y)[0];
    if (hit) fire(hit);
  };

  const tileX = (i) => TX0 + i * TW + TW / 2;
  const fire = (e) => {
    e.locked = true;
    log.push([e.v, Math.round((playTime - Math.max(e.born, lastShot)) * 1000), Math.max(flips, pop(e.v))]);
    lastShot = playTime;
    flips = 0;
    kills++;
    let k = 0;
    e.pending = pop(bits);
    for (let i = 0; i < 8; i++) if (bits & (1 << (7 - i))) rockets.push({ sx: tileX(i), sy: TILE_Y - 18, e, t: -k++ * 0.035, dur: 0.38 + Math.random() * 0.1, bend: (Math.random() - 0.5) * 90 });
    bits = 0;
    tone(180, 900, 0.22, "sawtooth", 0.03);
  };

  const explode = (e) => {
    if (e.dead) return;
    e.dead = true;
    const cx = e.x + EW / 2, cy = e.y + 20;
    for (let i = 0; i < 26; i++) {
      const a = Math.random() * 6.28, sp = 60 + Math.random() * 220;
      parts.push({ x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 60, life: 0.5 + Math.random() * 0.4, t: 0, c: Math.random() < 0.5 ? e.color : "#ffffff", s: Math.random() < 0.3 ? 6 : 4 });
    }
    floats.push({ x: cx, y: e.y, t: 0, text: "+1" });
    enemies.splice(enemies.indexOf(e), 1);
    shake = Math.max(shake, 5);
    boom();
  };

  const gameOver = (e) => {
    phase = "over";
    died = e.v;
    e.crashed = true;
    overT = 0;
    shake = 14;
    boom(0.7, 0.18);
    tone(420, 70, 0.9, "square", 0.05);
  };

  let quietUntil = 0;
  const finish = () => {
    phase = "done";
    quietUntil = performance.now() + 1500;
    etude.submit({ log: log.slice(), ms: Math.round(playTime * 1000), died });
  };

  // ---------------------------------------------------------------- update
  const update = (dt) => {
    blink += dt;
    for (let i = 0; i < 8; i++) tileBump[i] = Math.max(0, tileBump[i] - dt * 6);
    shake = Math.max(0, shake - dt * 30);
    for (const p of parts) { p.t += dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vy += 420 * dt; }
    for (let i = parts.length - 1; i >= 0; i--) if (parts[i].t > parts[i].life) parts.splice(i, 1);
    for (const f of floats) f.t += dt;
    for (let i = floats.length - 1; i >= 0; i--) if (floats[i].t > 0.8) floats.splice(i, 1);
    if (toast) { toast.t += dt; if (toast.t > 1.2) toast = null; }

    if (phase === "over") { overT += dt; if (overT > 2.2) finish(); return; }
    if (phase !== "play") return;
    playTime += dt;
    spawnT -= dt;
    if (!enemies.some((e) => !e.locked)) spawnT = Math.min(spawnT, 0.5);
    if (spawnT <= 0) { spawn(); spawnT = interval(); }
    const v = fallSpeed();
    for (const e of enemies) {
      if (!e.locked) e.y += v * dt;
      if (!e.locked && e.y + EH >= GROUND) { e.y = GROUND - EH; return gameOver(e); }
    }
    for (const e of enemies) if (e.hitT) e.hitT = Math.max(0, e.hitT - dt);
    for (const r of rockets) {
      r.t += dt / r.dur;
      if (r.t >= 1 && !r.done) {
        r.done = true;
        // Every rocket hits; the invader goes when the last one lands.
        const hx = r.e.x + EW / 2, hy = r.e.y + 30;
        for (let k = 0; k < 5; k++) parts.push({ x: hx, y: hy, vx: (Math.random() - 0.5) * 160, vy: (Math.random() - 0.5) * 160, life: 0.25, t: 0, c: C.flame, s: 3 });
        if (--r.e.pending <= 0) explode(r.e);
        else { tone(900, 500, 0.05, "square", 0.025); r.e.hitT = 0.12; }
      }
    }
    for (let i = rockets.length - 1; i >= 0; i--) if (rockets[i].done) rockets.splice(i, 1);
  };

  // ---------------------------------------------------------------- draw
  const px = (pattern, x, y, s, color) => {
    ctx.fillStyle = color;
    pattern.forEach((row, j) => { for (let i = 0; i < row.length; i++) if (row[i] === "X") ctx.fillRect(x + i * s, y + j * s, s, s); });
  };
  const text = (s, x, y, size, color, align = "center") => {
    ctx.font = font(size);
    ctx.textAlign = align;
    ctx.textBaseline = "middle";
    ctx.fillStyle = color;
    ctx.fillText(s, x, y);
  };
  const rocketAt = (x, y, flame, angle = 0) => {
    if (angle) { ctx.save(); ctx.translate(x, y + 7.5); ctx.rotate(angle); x = 0; y = -7.5; }
    px(ROCKET, x - 4.5, y, 3, "#e8ecff");
    if (flame) { ctx.fillStyle = C.flame; ctx.fillRect(x - 1.5, y + 15, 3, 4 + (Math.random() * 5) | 0); }
    if (angle) ctx.restore();
  };

  let scale = 1;
  const draw = () => {
    ctx.setTransform(scale, 0, 0, scale, 0, 0);
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = C.bg;
    ctx.fillRect(0, 0, W, H);
    if (shake > 0.2) ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);

    for (const s of stars) { ctx.globalAlpha = 0.35 + 0.4 * Math.sin(blink * 1.7 + s.ph) ** 2; ctx.fillStyle = C.star; ctx.fillRect(s.x | 0, s.y | 0, s.s, s.s); }
    ctx.globalAlpha = 1;
    for (const b of city) {
      ctx.fillStyle = C.city;
      ctx.fillRect(b.x, GROUND - b.h, b.w, b.h);
      ctx.fillStyle = C.cityLit;
      b.lit.forEach((on, k) => { if (on) ctx.fillRect(b.x + 4 + (k % 2) * 8, GROUND - b.h + 6 + Math.floor(k / 2) * 10, 3, 3); });
    }
    ctx.fillStyle = C.ground;
    ctx.fillRect(0, GROUND, W, TILE_Y - GROUND - 26);
    ctx.fillStyle = phase === "over" ? C.danger : C.groundTop;
    ctx.fillRect(0, GROUND, W, 3);

    const hud = () => {
    ctx.fillStyle = C.bg;
    ctx.fillRect(0, 0, W, 34);
    ctx.fillStyle = "#1a2346";
    ctx.fillRect(0, 34, W, 2);
    text(`SCORE ${kills}`, 12, 18, 14, C.text, "left");
    text(BASE_NAME, W - 44, 18, 14, C.dim, "right");
    ctx.fillStyle = sound ? C.text : C.dim;
    ctx.fillRect(W - 32, 14, 4, 8); ctx.fillRect(W - 28, 11, 3, 14); ctx.fillRect(W - 25, 8, 3, 20);
    if (sound) { ctx.fillRect(W - 19, 13, 2, 10); ctx.fillRect(W - 15, 10, 2, 16); }
    else { ctx.fillStyle = C.danger; for (let k = 0; k < 5; k++) { ctx.fillRect(W - 20 + k * 2, 12 + k * 2, 2, 2); ctx.fillRect(W - 20 + k * 2, 20 - k * 2, 2, 2); } }
    };

    // invaders
    const frame = Math.floor(blink * 2) % 2;
    for (const e of enemies) {
      const flash = (e.crashed && Math.floor(overT * 8) % 2 === 0) || e.hitT > 0;
      const col = flash ? "#ffffff" : e.color;
      ctx.globalAlpha = Math.min(1, (playTime - e.born) / 0.25 + 0.15);
      px(SPRITES[(frame + (e.ph > 0.5 ? 1 : 0)) % 2], e.x + 6, e.y, 4, col);
      ctx.fillStyle = flash ? C.danger : "#141b36";
      ctx.fillRect(e.x, e.y + 35, EW, 23);
      ctx.fillStyle = col;
      ctx.fillRect(e.x, e.y + 35, EW, 2); ctx.fillRect(e.x, e.y + 56, EW, 2); ctx.fillRect(e.x, e.y + 35, 2, 23); ctx.fillRect(e.x + EW - 2, e.y + 35, 2, 23);
      text(fmt(e.v), e.x + EW / 2, e.y + 47, BASE === 2 ? 9 : 16, "#ffffff");
      if (e.locked && Math.floor(blink * 12) % 2 === 0) {
        ctx.fillStyle = "#ffffff";
        for (const [cx, cy, dx, dy] of [[e.x - 5, e.y - 5, 1, 1], [e.x + EW + 5, e.y - 5, -1, 1], [e.x - 5, e.y + EH + 5, 1, -1], [e.x + EW + 5, e.y + EH + 5, -1, -1]]) {
          ctx.fillRect(Math.min(cx, cx + dx * 10), cy - (dy < 0 ? 2 : 0), 10, 2);
          ctx.fillRect(cx - (dx < 0 ? 2 : 0), Math.min(cy, cy + dy * 10), 2, 10);
        }
      }
      ctx.globalAlpha = 1;
    }

    // rockets in flight
    for (const r of rockets) {
      if (r.t < 0) { rocketAt(r.sx, r.sy, false); continue; }
      const t = Math.min(1, r.t), ex = r.e.x + EW / 2, ey = r.e.y + 30;
      const cx = r.sx + r.bend, cy = r.sy - 120 - Math.abs(r.bend);
      const x = (1 - t) ** 2 * r.sx + 2 * (1 - t) * t * cx + t * t * ex;
      const y = (1 - t) ** 2 * r.sy + 2 * (1 - t) * t * cy + t * t * ey;
      const B = (tt) => [(1 - tt) ** 2 * r.sx + 2 * (1 - tt) * tt * cx + tt * tt * ex, (1 - tt) ** 2 * r.sy + 2 * (1 - tt) * tt * cy + tt * tt * ey];
      for (let k = 1; k <= 12; k++) {
        const [tx, ty] = B(Math.max(0, t - k * 0.018));
        ctx.globalAlpha = 0.75 * (1 - k / 13);
        ctx.fillStyle = k < 4 ? "#ffd166" : C.flame;
        const sz = k < 4 ? 4 : 3;
        ctx.fillRect(tx - sz / 2, ty - sz / 2, sz, sz);
      }
      ctx.globalAlpha = 1;
      const dx = 2 * (1 - t) * (cx - r.sx) + 2 * t * (ex - cx), dy = 2 * (1 - t) * (cy - r.sy) + 2 * t * (ey - cy);
      rocketAt(x, y - 8, true, Math.atan2(dx, -dy));
    }
    for (const p of parts) { ctx.globalAlpha = Math.max(0, 1 - p.t / p.life); ctx.fillStyle = p.c; ctx.fillRect(p.x | 0, p.y | 0, p.s, p.s); }
    ctx.globalAlpha = 1;
    for (const f of floats) { ctx.globalAlpha = 1 - f.t / 0.8; text(f.text, f.x, f.y - f.t * 40, 14, C.tileOn); }
    ctx.globalAlpha = 1;

    // the bits
    for (let i = 0; i < 8; i++) {
      const on = (bits >> (7 - i)) & 1, x = TX0 + i * TW + 3, y = TILE_Y - tileBump[i] * 6;
      if (on) rocketAt(tileX(i), TILE_Y - 22 - tileBump[i] * 6, false);
      ctx.fillStyle = on ? C.tileOn : C.tileOff;
      ctx.fillRect(x, y, TW - 6, TILE_H);
      ctx.fillStyle = on ? "#c99a2e" : C.tileOffEdge;
      ctx.fillRect(x, y + TILE_H - 4, TW - 6, 4);
      text(on ? "1" : "0", x + (TW - 6) / 2, y + TILE_H / 2 - 2, 28, on ? C.tileOnText : C.tileOffText);
      text(ROWS[0][i], x + 6, y + 10, 10, on ? "#8a6a1f" : "#4a5a92", "left");
      if (HINTS) text(String(1 << (7 - i)), x + (TW - 6) / 2, TILE_Y + TILE_H + 13, 12, "#8f9cd0");
    }
    // what the bits spell right now
    const ry = HINTS ? 556 : 548;
    if (HINTS && BASE !== 10) {
      const a = fmt(bits), b = `  =  ${bits}`;
      ctx.font = font(20); const wa = ctx.measureText(a).width;
      ctx.font = font(14); const wb = ctx.measureText(b).width;
      const x0 = W / 2 - (wa + wb) / 2;
      text(a, x0, ry, 20, bits ? C.tileOn : C.dim, "left");
      text(b, x0 + wa, ry + 1, 14, "#8f9cd0", "left");
    } else text(fmt(bits), W / 2, ry, 20, bits ? C.tileOn : C.dim);
    hud();

    // overlays
    ctx.setTransform(scale, 0, 0, scale, 0, 0);
    const veil = (a) => { ctx.fillStyle = `rgba(6,9,20,${a})`; ctx.fillRect(0, 36, W, H - 36); };
    if (phase === "title") {
      veil(0.72);
      text("FLIPPY BIT", W / 2, 130, 44, C.tileOn);
      text("AND THE ATTACK OF THE", W / 2, 178, 12, C.dim);
      text(BASE === 16 ? "HEXADECIMALS" : "NUMBERS", W / 2, 204, 22, C.inv[0]);
      text(`FROM BASE ${BASE}`, W / 2, 230, 12, C.dim);
      if (Math.floor(blink * 2) % 2 === 0) text("PRESS A KEY OR TAP TO START", W / 2, 300, 13, C.text);
      text("FLIP THE BITS UNTIL THEY SPELL", W / 2, 346, 10, C.dim);
      text("AN INVADER'S NUMBER. THEN IT'S TOAST.", W / 2, 364, 10, C.dim);
    } else if (phase === "paused") {
      veil(0.65);
      text("PAUSED", W / 2, 180, 32, C.text);
      text("CLICK OR PRESS A KEY", W / 2, 224, 12, C.dim);
    } else if (phase === "over" || phase === "done") {
      veil(Math.min(0.86, overT * 1.4));
      if (overT > 0.5) {
        ctx.fillStyle = C.bg;
        ctx.fillRect(40, 104, W - 80, 186);
        ctx.fillStyle = C.danger;
        ctx.fillRect(40, 104, W - 80, 2); ctx.fillRect(40, 288, W - 80, 2);
        text("GAME OVER", W / 2, 140, 38, C.danger);
        text(`${kills} INVADER${kills === 1 ? "" : "S"}`, W / 2, 188, 16, C.text);
        if (died !== null) {
          text(`${fmt(died)} WAS ${bin(died)}`, W / 2, 240, 16, C.tileOn);
          if (BASE !== 10) text(`${bits ? `YOU HAD ${bin(bits)}  ·  ` : ""}${BASE === 16 ? "0x" : ""}${fmt(died)} = ${died}`, W / 2, 268, 12, "#aab5e6");
        }
      }
    }
    if (toast) { ctx.globalAlpha = Math.min(1, 3 * (1.2 - toast.t)); text(toast.text, W / 2, 60, 12, C.text); ctx.globalAlpha = 1; }
  };

  // ---------------------------------------------------------------- loop, sizing, input
  const resize = () => {
    const cw = Math.min(stage.clientWidth || W, W), ch = (cw * H) / W, dpr = window.devicePixelRatio || 1;
    canvas.style.width = `${cw}px`;
    canvas.style.height = `${ch}px`;
    canvas.width = Math.round(cw * dpr);
    canvas.height = Math.round(ch * dpr);
    scale = (cw / W) * dpr;
    draw();
  };
  new ResizeObserver(resize).observe(stage);
  resize();

  let last = performance.now(), running = true;
  const loop = (now) => {
    if (!running) return;
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    update(dt);
    draw();
    // State on the element, for tests and tools (the numbers are on screen anyway).
    const low = enemies.filter((e) => !e.locked).sort((a, b) => b.y - a.y)[0];
    stage.dataset.phase = phase;
    stage.dataset.kills = kills;
    stage.dataset.bits = bits;
    stage.dataset.next = low ? low.v : "";
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);

  const pause = () => { if (phase === "play") phase = "paused"; };
  window.addEventListener("blur", pause);
  document.addEventListener("visibilitychange", () => { if (document.hidden) pause(); });

  window.addEventListener("keydown", (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey || e.key === "Escape" || e.key === "Tab") return;
    // Keys mashed while dying shouldn't press Next or rate the card; after a moment they go to the app again.
    if (phase === "done") { if (performance.now() < quietUntil) e.preventDefault(); return; }
    const k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
    if (k.length === 1 || k === "Enter") e.preventDefault();
    if (e.repeat) return;
    if (k in keyBit) return flip(keyBit[k]);
    if (phase === "title" && (k === " " || k === "Enter")) return start();
    if (phase === "paused") phase = "play";
  }, true);

  const toLocal = (ev) => { const r = canvas.getBoundingClientRect(); return { x: ((ev.clientX - r.left) * W) / r.width, y: ((ev.clientY - r.top) * H) / r.height }; };
  const tileAt = (p) => (p.y >= TILE_Y - 34 && p.y <= TILE_Y + TILE_H + 22 ? Math.max(0, Math.min(7, Math.floor((p.x - TX0) / TW))) : -1);
  let drag = -1;
  canvas.addEventListener("pointerdown", (ev) => {
    ev.preventDefault();
    stage.focus({ preventScroll: true });
    const p = toLocal(ev);
    if (p.y < 34 && p.x > W - 40) {
      sound = !sound;
      toast = { t: 0, text: sound ? "SOUND ON" : "SOUND OFF" };
      if (sound) tone(500, 700, 0.08, "square", 0.04);
      return;
    }
    if (phase === "title") return start();
    if (phase === "paused") { phase = "play"; return; }
    const i = tileAt(p);
    if (i >= 0) { flip(i); drag = i; canvas.setPointerCapture(ev.pointerId); }
  });
  canvas.addEventListener("pointermove", (ev) => {
    if (drag < 0) return;
    const i = tileAt(toLocal(ev));
    if (i >= 0 && i !== drag) { flip(i); drag = i; }
  });
  const up = () => { drag = -1; };
  canvas.addEventListener("pointerup", up);
  canvas.addEventListener("pointercancel", up);

  etude.setReady(false);
  etude.getAnswer(() => ({ log: log.slice(), ms: Math.round(playTime * 1000), died }));
  etude.onResult(() => { running = false; phase = "done"; });
}

// ---------------------------------------------------------------- result
etude.onResult(({ grade, answer }) => {
  const d = grade?.details;
  const $ = (s) => etude.$(s);
  const row = (v, extra = "") => `<div class="fb-row"><span class="fb-hex">${etude.escape(fmt(v))}</span><span class="fb-bin">${bin(v).replace(/1/g, '<b>1</b>')}</span>${BASE !== 10 ? `<span class="fb-dec">${v}</span>` : ""}${extra}</div>`;
  if (!d) {
    for (const s of [".fb-kills", ".fb-per", ".fb-clean", ".fb-time"]) $(s).textContent = "–";
    $(".fb-got").innerHTML = `<span class="e-muted">Play a run and the invader that got you shows up here.</span>`;
    for (const s of [".fb-sec-slow", ".fb-sec-shot"]) $(s).hidden = true;
    return;
  }
  $(".fb-kills").textContent = d.kills;
  $(".fb-per").textContent = d.perKill == null ? "–" : `${d.perKill.toFixed(1)} s`;
  $(".fb-clean").textContent = d.clean == null ? "–" : `${Math.round(d.clean)}%`;
  $(".fb-time").textContent = `${Math.round(d.seconds)} s`;
  if (d.died != null) $(".fb-got").innerHTML = row(d.died);
  else $(".fb-sec-got").hidden = true;
  const log = Array.isArray(d.log) ? d.log : [];
  const slow = [...log].sort((a, b) => b[1] - a[1]).slice(0, 3);
  if (log.length >= 4) $(".fb-slow").innerHTML = slow.map((e) => row(e[0], `<span class="fb-t">${(e[1] / 1000).toFixed(1)} s</span>`)).join("");
  else $(".fb-sec-slow").hidden = true;
  if (log.length) $(".fb-shot").innerHTML = log.slice(0, 120).map((e) => `<span class="fb-chip" title="${bin(e[0])} = ${e[0]} · ${(e[1] / 1000).toFixed(1)} s">${etude.escape(fmt(e[0]))}</span>`).join("");
  else $(".fb-sec-shot").hidden = true;
});

grader.code:
const given = Array.isArray(answer) ? answer.map(String) : [];
const order = key.order;
let k = 0;
while (k < order.length && given[k] === order[k]) k++;
// The start node is placed for the learner, so it doesn't earn credit.
const score = order.length > 1 ? Math.max(0, k - 1) / (order.length - 1) : 1;
let feedback;
const name = view.algorithm === "bfs" ? "BFS" : "DFS";
if (k < order.length) {
  if (k >= given.length) feedback = `Correct for the first ${k} nodes, then the order stopped. ${name} visits ${order[k]} next.`;
  else feedback = `Correct for the first ${k} node${k === 1 ? "" : "s"}. Step ${k + 1} is ${order[k]}, not ${given[k]}. (${Math.max(0, k - 1)} of ${order.length - 1} moves after the start.)`;
}
return { score, feedback, details: { prefix: k, given } };

types.prepare:
// A connected graph on a jittered 3×3 grid. Edges only join neighbouring cells (and at most one
// diagonal per square), so no edge crosses a node or another edge.
const W = 3, H = 3;
const want = Number(fields.size);
const n = want >= 6 && want <= 9 ? Math.round(want) : rng.int(6, 9);
const cell = (c, r) => r * W + c;
const neigh = (i) => {
  const c = i % W, r = Math.floor(i / W), out = [];
  for (const [dc, dr] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const cc = c + dc, rr = r + dr;
    if (cc >= 0 && cc < W && rr >= 0 && rr < H) out.push(cell(cc, rr));
  }
  return out;
};
// Grow a connected set of n cells from a random one.
const cells = [rng.int(0, W * H - 1)];
while (cells.length < n) {
  const frontier = [...new Set(cells.flatMap(neigh))].filter((x) => !cells.includes(x));
  cells.push(rng.pick(frontier));
}
const used = new Set(cells);
const cand = [];
for (const a of cells) {
  const c = a % W, r = Math.floor(a / W);
  if (c + 1 < W && used.has(cell(c + 1, r))) cand.push([a, cell(c + 1, r)]);
  if (r + 1 < H && used.has(cell(c, r + 1))) cand.push([a, cell(c, r + 1)]);
  // One diagonal per square at most.
  if (c + 1 < W && r + 1 < H) {
    const d1 = [a, cell(c + 1, r + 1)], d2 = [cell(c + 1, r), cell(c, r + 1)];
    const ok1 = used.has(d1[1]), ok2 = used.has(d2[0]) && used.has(d2[1]);
    if (ok1 && ok2) cand.push(rng.bool() ? d1 : d2);
    else if (ok1) cand.push(d1);
    else if (ok2) cand.push(d2);
  }
}
// Random spanning tree over the candidates (Kruskal on a shuffle), then a few extra edges.
const parent = {};
const find = (x) => (parent[x] === undefined || parent[x] === x ? x : (parent[x] = find(parent[x])));
const edges = [], extra = [];
for (const e of rng.shuffle(cand)) {
  const a = find(e[0]), b = find(e[1]);
  if (a !== b) { parent[a] = b; edges.push(e); } else extra.push(e);
}
const extras = Math.min(extra.length, rng.int(1, 3));
edges.push(...extra.slice(0, extras));

// Letters are assigned at random so alphabetical order isn't left-to-right.
const letters = rng.shuffle("ABCDEFGHI".slice(0, n).split(""));
const label = Object.fromEntries(cells.map((c, i) => [c, letters[i]]));
const nodes = cells.map((c) => ({
  id: label[c],
  x: 66 + (c % W) * 120 + rng.int(-14, 14),
  y: 48 + Math.floor(c / W) * 102 + rng.int(-12, 12),
})).sort((a, b) => a.id.localeCompare(b.id));
const edgeList = edges.map(([a, b]) => [label[a], label[b]].sort()).sort((p, q) => (p[0] + p[1]).localeCompare(q[0] + q[1]));

const adj = Object.fromEntries(nodes.map((v) => [v.id, []]));
for (const [a, b] of edgeList) { adj[a].push(b); adj[b].push(a); }
for (const k in adj) adj[k].sort();

let algo = String(fields.algorithm ?? "bfs").toLowerCase();
if (algo !== "bfs" && algo !== "dfs") algo = rng.pick(["bfs", "dfs"]);
const start = rng.pick(nodes).id;
const order = [], tree = [], seen = new Set([start]);
if (algo === "bfs") {
  const q = [start];
  while (q.length) {
    const v = q.shift();
    order.push(v);
    for (const w of adj[v]) if (!seen.has(w)) { seen.add(w); tree.push([v, w]); q.push(w); }
  }
} else {
  const visit = (v) => {
    order.push(v);
    for (const w of adj[v]) if (!seen.has(w)) { seen.add(w); tree.push([v, w]); visit(w); }
  };
  visit(start);
}
return {
  view: { algorithm: algo, start, nodes, edges: edgeList, note: fields.note ?? "" },
  key: { order, tree, explanation: fields.explanation ?? "" },
};

template.css:
.sc-eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted-foreground); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.85rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.75rem; margin: 0.25rem 0 0; }

/* Code should read literally: no fused glyphs from ligature fonts. */
#card, #card * { font-variant-ligatures: none; font-feature-settings: "liga" 0, "calt" 0; }

.gw-prompt .rule { color: var(--muted-foreground); font-size: 0.95rem; }
.gw-stage { display: flex; justify-content: center; }
.gw-svg { width: 100%; max-width: 440px; height: auto; display: block; touch-action: manipulation; user-select: none; -webkit-user-select: none; -webkit-tap-highlight-color: transparent; }

.gw-edge { stroke: color-mix(in oklab, var(--foreground) 40%, transparent); stroke-width: 2.25; stroke-linecap: round; transition: stroke 0.3s, stroke-width 0.3s; }
.gw-edge.tree { stroke: var(--highlight); stroke-width: 3.5; }

.gw-node { cursor: pointer; outline: none; }
.gw-node .hit { fill: transparent; }
.gw-node .disc { fill: var(--background); stroke: color-mix(in oklab, var(--foreground) 45%, transparent); stroke-width: 2; transition: fill 0.2s, stroke 0.2s; }
.gw-node .lbl { fill: var(--foreground); font: 600 17px var(--font-sans); text-anchor: middle; dominant-baseline: central; pointer-events: none; }
.gw-node .num { fill: var(--background); font: 700 11px var(--font-sans); text-anchor: middle; dominant-baseline: central; pointer-events: none; }
.gw-node .badge { fill: var(--highlight); stroke: var(--background); stroke-width: 2.5; opacity: 0; transition: opacity 0.15s; }
.gw-node.picked .badge, .gw-node.picked .num { opacity: 1; }
.gw-node .num { opacity: 0; }
.gw-node.picked .disc { stroke: var(--highlight); fill: color-mix(in oklab, var(--highlight) 14%, var(--background)); }
.gw-node.start .disc { stroke: var(--foreground); stroke-width: 3; }
.gw-node.last .disc { stroke-dasharray: 4 3; }
.gw-node:hover .disc { stroke: var(--foreground); }
.gw-node:focus-visible .disc { stroke: var(--ring); stroke-width: 4; }
[data-mode="result"] .gw-node { cursor: default; }
.gw-node.ok .badge { fill: var(--success); }
.gw-node.bad .badge { fill: var(--danger); }
.gw-node.after .badge { fill: var(--muted-foreground); }
.gw-node.lit .disc { fill: color-mix(in oklab, var(--highlight) 30%, var(--background)); stroke: var(--highlight); stroke-width: 3; }
.gw-node.lit .lbl { fill: var(--foreground); }
.gw-node.lit-now .disc { stroke-width: 5; }

.hop { display: inline-flex; align-items: center; gap: 0.35rem; }
.gw-seq { display: flex; flex-wrap: wrap; gap: 0.35rem; align-items: center; min-height: 2rem; font-family: var(--font-mono); font-size: 0.95rem; }
