const mine = etude.$(".mo-mine");
if (etude.view.prosign) etude.$(".mo-letter").classList.add("is-prosign");
const MAX = 9; // the longest code here is SOS, ...---...
let seq = typeof etude.answer === "string" ? etude.answer : "";
const sym = (s, cls = "") => `<span class="mo-sym ${s === "." ? "dot" : "dash"} ${cls}"></span>`;

const draw = (fresh) => {
  mine.innerHTML = seq ? [...seq].map((s, i) => sym(s, fresh && i === seq.length - 1 ? "new" : "")).join("") : `<span class="mo-empty">Tap dot and dash</span>`;
  mine.classList.toggle("long", seq.length > 6);
  etude.setReady(seq.length > 0);
};
const press = (s) => {
  if (etude.mode !== "answer") return;
  seq = s === "del" ? seq.slice(0, -1) : (seq + s).slice(0, MAX);
  draw(s !== "del");
};
etude.$$(".mo-key").forEach((b) => b.addEventListener("click", () => press(b.dataset.s)));
window.addEventListener("keydown", (e) => {
  const s = { ".": ".", "-": "-", j: ".", k: "-", Backspace: "del" }[e.key];
  if (!s || etude.mode !== "answer") return;
  e.preventDefault();
  press(s);
  const b = etude.$(`.mo-key[data-s="${s}"]`);
  b?.classList.add("down");
  setTimeout(() => b?.classList.remove("down"), 120);
});
draw(false);
etude.getAnswer(() => seq);

etude.onResult(({ key, answer }) => {
  const sent = String(answer ?? "");
  const code = key.code;
  // Your taps, marked symbol by symbol; anything you left out shows faded.
  mine.innerHTML = [...sent].map((s, i) => sym(s, s === code[i] ? "is-ok" : "is-bad")).join("") +
    [...code.slice(sent.length)].map((s) => sym(s, "is-missed")).join("");
  mine.classList.toggle("long", Math.max(sent.length, code.length) > 6);
  const right = etude.$(".mo-correct");
  right.classList.toggle("long", code.length > 6);
  right.innerHTML = [...code].map((s) => sym(s)).join("");
  // Blink the right code on the lamp at Morse timing: dot 1 unit, dash 3, gaps 1, then a pause.
  const lamp = etude.$(".mo-lamp");
  const parts = etude.$$(".mo-correct .mo-sym");
  const U = 170;
  const loop = (i) => {
    if (!lamp.isConnected) return;
    if (i === code.length) return setTimeout(() => loop(0), 6 * U);
    lamp.classList.add("on"); parts[i].classList.add("lit");
    setTimeout(() => {
      lamp.classList.remove("on"); parts[i].classList.remove("lit");
      setTimeout(() => loop(i + 1), U);
    }, code[i] === "." ? U : 3 * U);
  };
  setTimeout(() => loop(0), 400);
});

grader.code:
// Best one-to-one matching of placed points to expected points (brute force; a handful of points).
const placed = (Array.isArray(answer) ? answer : []).filter((p) => Array.isArray(p) && p.every(Number.isFinite)).slice(0, 12);
const want = key.points;
const tol = key.tolerance;
const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]);

let best = { hits: -1, total: Infinity, pairs: [] };
function search(i, used, pairs, hits, total) {
  if (i === want.length) {
    if (hits > best.hits || (hits === best.hits && total < best.total)) best = { hits, total, pairs: pairs.slice() };
    return;
  }
  // leave expected point i unmatched
  pairs.push(-1);
  search(i + 1, used, pairs, hits, total);
  pairs.pop();
  for (let j = 0; j < placed.length; j++) {
    if (used & (1 << j)) continue;
    const d = dist(want[i], placed[j]);
    if (d > tol + 1e-9) continue;
    pairs.push(j);
    search(i + 1, used | (1 << j), pairs, hits + 1, total + d);
    pairs.pop();
  }
}
search(0, 0, [], 0, 0);

const hits = best.hits;
const matched = new Set(best.pairs.filter((j) => j >= 0));
const extras = placed.map((_, j) => j).filter((j) => !matched.has(j));
const score = want.length ? Math.max(0, (hits - 0.5 * extras.length) / want.length) : extras.length ? 0 : 1;
let feedback;
const missed = want.length - hits;
if (score < 1) {
  const bits = [];
  if (hits) bits.push(`${hits} of ${want.length} right`);
  if (missed) bits.push(`${missed} missed`);
  if (extras.length) bits.push(`${extras.length} extra (each costs half a point)`);
  feedback = bits.join(", ") + ".";
}
return {
  score: Math.round(score * 100) / 100,
  feedback,
  details: { placed, match: best.pairs, extras },
};

types.prepare:
const points = (Array.isArray(fields.points) ? fields.points : []).map((p) => [Number(p[0]), Number(p[1])]);
const r = Array.isArray(fields.range) && fields.range.length === 4 ? fields.range.map(Number) : [-5, 5, -5, 5];
return {
  view: {
    prompt: fields.prompt,
    count: points.length,
    range: r,
    snap: typeof fields.snap === "number" ? fields.snap : 0.5,
  },
  key: {
    points,
    labels: Array.isArray(fields.labels) ? fields.labels : [],
    tolerance: typeof fields.tolerance === "number" ? fields.tolerance : 0.25,
    curve: fields.curve ?? "",
    explanation: fields.explanation ?? "",
  },
};

