const { view } = etude;
const NS = "http://www.w3.org/2000/svg";
const el = (tag, attrs = {}, text) => {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
  if (text != null) n.textContent = text;
  return n;
};
const [x0, x1, y0, y1] = view.range;
const PAD = 0.7;
const svg = etude.$(".pl-svg");
// One SVG unit is one grid unit; y is flipped with a transform on each element instead of the viewBox.
svg.setAttribute("viewBox", `${x0 - PAD} ${-(y1 + PAD)} ${x1 - x0 + 2 * PAD} ${y1 - y0 + 2 * PAD}`);
const Y = (y) => -y;
const snap = view.snap > 0 ? view.snap : 0;
const fmt = (v) => (v < 0 ? "\u2212" : "") + String(Math.abs(Math.round(v * 100) / 100));

// Grid, axes and tick labels.
const grid = etude.$(".pl-grid");
for (let x = Math.ceil(x0); x <= x1; x++) grid.append(el("line", { x1: x, y1: Y(y0), x2: x, y2: Y(y1), class: x === 0 ? "axis" : "" }));
for (let y = Math.ceil(y0); y <= y1; y++) grid.append(el("line", { x1: x0, y1: Y(y), x2: x1, y2: Y(y), class: y === 0 ? "axis" : "" }));
const ax = Math.max(x0, Math.min(x1, 0)), ay = Math.max(y0, Math.min(y1, 0));
grid.append(el("path", { d: `M${x1 + 0.45},${Y(ay)} l-0.2,-0.1 v0.2 Z`, class: "arrow" }));
grid.append(el("path", { d: `M${ax},${Y(y1 + 0.45)} l-0.1,0.2 h0.2 Z`, class: "arrow" }));
grid.append(el("line", { x1: x1, y1: Y(ay), x2: x1 + 0.3, y2: Y(ay), class: "axis" }));
grid.append(el("line", { x1: ax, y1: Y(y1), x2: ax, y2: Y(y1 + 0.3), class: "axis" }));
// Labels are HTML over the SVG so they render in KaTeX.
const tags = etude.$(".pl-tags");
const VW = x1 - x0 + 2 * PAD, VH = y1 - y0 + 2 * PAD;
const label = (x, y, texSrc, cls) => {
  const s = document.createElement("span");
  s.className = cls;
  s.style.left = ((x - x0 + PAD) / VW) * 100 + "%";
  s.style.top = ((y1 + PAD - y) / VH) * 100 + "%";
  s.innerHTML = etude.mdInline("$" + texSrc + "$");
  tags.append(s);
  return s;
};
const every = x1 - x0 > 14 ? 2 : 1;
for (let x = Math.ceil(x0); x <= x1; x++) if (x !== 0 && x % every === 0) label(x, ay - 0.36, String(x), "pl-tick");
for (let y = Math.ceil(y0); y <= y1; y++) if (y !== 0 && y % every === 0) label(ax - 0.3, y, String(y), "pl-tick left");
label(ax - 0.28, ay - 0.36, "0", "pl-tick");
label(x1 + 0.35, ay + 0.3, "x", "pl-var");
label(ax + 0.32, y1 + 0.35, "y", "pl-var");

// Placed points.
let pts = Array.isArray(etude.answer) ? etude.answer.map((p) => [Number(p[0]), Number(p[1])]) : [];
const placedG = etude.$(".pl-placed");
const count = etude.$(".pl-count");
const draw = () => {
  placedG.replaceChildren(...pts.map((p, i) => el("circle", { cx: p[0], cy: Y(p[1]), r: 0.17, class: "pt", "data-i": i })));
  const n = pts.length, want = view.count;
  count.innerHTML = `<b>${n}</b> of ${want} point${want === 1 ? "" : "s"}`;
  count.classList.toggle("over", n > want);
  count.classList.toggle("full", n === want);
  if (etude.mode === "answer") etude.setReady(n > 0);
};

const toWorld = (e) => {
  const pt = svg.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  const p = pt.matrixTransform(svg.getScreenCTM().inverse());
  return [p.x, -p.y];
};
const snapTo = ([x, y]) => {
  const s = (v) => (snap ? Math.round(v / snap) * snap : Math.round(v * 100) / 100);
  return [Math.max(x0, Math.min(x1, s(x))), Math.max(y0, Math.min(y1, s(y)))];
};
// Hit radius of about 22 CSS px, whatever the grid's size on screen.
const unitPx = () => svg.getBoundingClientRect().width / (x1 - x0 + 2 * PAD);
const hit = (w) => {
  const r = 22 / unitPx();
  let best = -1, bd = Infinity;
  pts.forEach((p, i) => {
    const d = Math.hypot(p[0] - w[0], p[1] - w[1]);
    if (d < r && d < bd) (best = i), (bd = d);
  });
  return best;
};

const cursor = etude.$(".pl-cursor");
let drag = null;
svg.addEventListener("pointerdown", (e) => {
  if (etude.mode !== "answer") return;
  e.preventDefault();
  const w = toWorld(e);
  const i = hit(w);
  svg.setPointerCapture(e.pointerId);
  if (i >= 0) drag = { i, moved: false, sx: e.clientX, sy: e.clientY, fresh: false };
  else {
    const p = snapTo(w);
    if (p[0] < x0 - 1e-9 || p[0] > x1 + 1e-9) return;
    pts.push(p);
    drag = { i: pts.length - 1, moved: true, sx: e.clientX, sy: e.clientY, fresh: true };
    draw();
  }
  svg.classList.add("dragging");
});
svg.addEventListener("pointermove", (e) => {
  if (etude.mode !== "answer") return;
  const w = toWorld(e);
  if (e.pointerType === "mouse" && !drag) {
    const p = snapTo(w);
    cursor.style.display = hit(w) >= 0 ? "none" : "";
    cursor.firstElementChild.setAttribute("cx", p[0]);
    cursor.firstElementChild.setAttribute("cy", Y(p[1]));
  }
  if (!drag) return;
  if (Math.hypot(e.clientX - drag.sx, e.clientY - drag.sy) > 6) drag.moved = true;
  if (drag.moved) {
    pts[drag.i] = snapTo(w);
    draw();
  }
});
const end = () => {
  if (!drag) return;
  if (!drag.moved && !drag.fresh) pts.splice(drag.i, 1);
  // Two points on the same spot are one point.
  pts = pts.filter((p, i) => pts.findIndex((q) => q[0] === p[0] && q[1] === p[1]) === i);
  drag = null;
  svg.classList.remove("dragging");
  draw();
};
svg.addEventListener("pointerup", end);
svg.addEventListener("pointercancel", end);
svg.addEventListener("pointerleave", () => (cursor.style.display = "none"));
etude.$(".pl-clear").addEventListener("click", () => {
  pts = [];
  draw();
});
// Keyboard: a cursor that arrows move by one snap step; Enter or Space places or removes a point there.
let kc = null;
const step = snap || 0.5;
const showKey = () => {
  cursor.style.display = kc ? "" : "none";
  if (!kc) return;
  cursor.firstElementChild.setAttribute("cx", kc[0]);
  cursor.firstElementChild.setAttribute("cy", Y(kc[1]));
  svg.setAttribute("aria-valuetext", `cursor at ${kc[0]}, ${kc[1]}`);
};
svg.addEventListener("keydown", (e) => {
  if (etude.mode !== "answer" || e.ctrlKey || e.metaKey || e.altKey) return;
  const d = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, 1], ArrowDown: [0, -1] }[e.key];
  if (d) {
    e.preventDefault();
    kc = kc ?? [Math.max(x0, Math.min(x1, 0)), Math.max(y0, Math.min(y1, 0))];
    const m = e.shiftKey ? 1 / step : 1;
    kc = snapTo([kc[0] + d[0] * step * m, kc[1] + d[1] * step * m]);
    showKey();
  } else if ((e.key === "Enter" || e.key === " ") && kc) {
    e.preventDefault();
    const i = pts.findIndex((p) => p[0] === kc[0] && p[1] === kc[1]);
    if (i >= 0) pts.splice(i, 1);
    else pts.push(kc.slice());
    draw();
  } else if (e.key === "Backspace" && pts.length) {
    e.preventDefault();
    pts.pop();
    draw();
  }
});
svg.addEventListener("blur", () => { kc = null; showKey(); });
cursor.style.display = "none";
draw();
etude.getAnswer(() => pts);

const texPt = (p) => `$\\left(${p.map((v) => String(Math.round(v * 100) / 100)).join(", ")}\\right)$`;

etude.onResult(({ grade, key }) => {
  svg.classList.add("done");
  cursor.remove();
  const preview = document.body.dataset.preview === "1";
  const d = grade?.details ?? {};
  const placed = Array.isArray(d.placed) ? d.placed : pts;
  const match = Array.isArray(d.match) ? d.match : [];
  const extras = new Set(Array.isArray(d.extras) ? d.extras : []);
  pts = placed;

  // The curve(s), sampled densely and broken where they leave the grid. Samples are kept for label placement.
  const samples = [];
  if (key.curve) {
    const g = etude.$(".pl-curves");
    for (const expr of String(key.curve).split(";").map((s) => s.trim()).filter(Boolean)) {
      let f;
      try { f = new Function("x", `with (Math) { return (${expr}); }`); } catch { continue; }
      let path = "", pen = false;
      const N = 400;
      for (let k = 0; k <= N; k++) {
        const x = x0 + ((x1 - x0) * k) / N;
        let y;
        try { y = Number(f(x)); } catch { y = NaN; }
        const ok = Number.isFinite(y) && y >= y0 - 0.5 && y <= y1 + 0.5;
        if (ok) path += `${pen ? "L" : "M"}${x.toFixed(3)},${Y(y).toFixed(3)} `;
        if (ok && y >= y0 && y <= y1) samples.push([x, y]);
        pen = ok;
      }
      if (path) g.append(el("path", { d: path, class: "curve" }));
    }
    svg.append(el("clipPath", { id: "pl-clip" }, null));
    svg.lastChild.append(el("rect", { x: x0, y: Y(y1), width: x1 - x0, height: y1 - y0 }));
    g.setAttribute("clip-path", "url(#pl-clip)");
  }

  // Expected points: solid when you got them, dashed rings when missed.
  const exp = etude.$(".pl-expected");
  key.points.forEach((p, i) => {
    const got = match[i] >= 0 && match[i] !== undefined;
    exp.append(el("circle", { cx: p[0], cy: Y(p[1]), r: key.tolerance > 0.2 ? key.tolerance : 0.22, class: "zone" }));
    exp.append(el("circle", { cx: p[0], cy: Y(p[1]), r: got || preview ? 0.16 : 0.24, class: preview ? "want" : got ? "want hit" : "want miss" }));
  });
  draw();
  placedG.querySelectorAll(".pt").forEach((c, i) => {
    if (preview) return;
    c.classList.add(extras.has(i) ? "extra" : "good");
  });
  if (preview) placedG.replaceChildren();

  // Coordinates beside each expected point: try spots around it and keep the one that crosses the least
  // (curve, axes and tick labels, other points, labels already placed).
  const tagEls = key.points.map((p, i) => label(p[0], p[1], `\\left(${p.map((v) => String(Math.round(v * 100) / 100)).join(", ")}\\right)`, "pl-tag" + (!preview && !(match[i] >= 0) ? " missed" : "")));
  const placeTags = () => {
    const unit = svg.getBoundingClientRect().width / VW; // px per grid unit
    if (!unit) return;
    const taken = [];
    const dots = [...key.points, ...placed];
    const hits = (bx) => {
      let c = 0;
      const m = 0.15; // the stroke has width
      for (const [sx, sy] of samples) if (sx > bx[0] - m && sx < bx[2] + m && sy > bx[1] - m && sy < bx[3] + m) c += 3;
      for (const [px, py] of dots) if (px > bx[0] - 0.2 && px < bx[2] + 0.2 && py > bx[1] - 0.2 && py < bx[3] + 0.2) c += 40;
      // the x-axis tick row and the y-axis tick column
      if (bx[1] < ay + 0.1 && bx[3] > ay - 0.6) c += 25;
      if (bx[0] < ax + 0.1 && bx[2] > ax - 0.7) c += 25;
      for (const t of taken) if (bx[0] < t[2] && bx[2] > t[0] && bx[1] < t[3] && bx[3] > t[1]) c += 60;
      if (bx[0] < x0 - PAD + 0.05 || bx[2] > x1 + PAD - 0.05 || bx[1] < y0 - PAD + 0.05 || bx[3] > y1 + PAD - 0.05) c += 200;
      return c;
    };
    key.points.forEach((p, i) => {
      const elT = tagEls[i];
      const w = elT.offsetWidth / unit, h = elT.offsetHeight / unit;
      let best = null;
      for (const r of [0.45, 0.8, 1.2]) {
        for (let k = 0; k < 16; k++) {
          const ang = (k / 16) * 2 * Math.PI;
          // centre such that the box edge is r away from the point in this direction
          const cx = p[0] + Math.cos(ang) * (r + w / 2 * Math.abs(Math.cos(ang))) ;
          const cy = p[1] + Math.sin(ang) * (r + h / 2 * Math.abs(Math.sin(ang)));
          const bx = [cx - w / 2, cy - h / 2, cx + w / 2, cy + h / 2];
          // A tag should sit nearer its own point than any other, or it reads as someone else's.
          const near = (q) => Math.hypot(Math.max(bx[0], Math.min(q[0], bx[2])) - q[0], Math.max(bx[1], Math.min(q[1], bx[3])) - q[1]);
          const own = near(p);
          const confusing = dots.some((q) => (q[0] !== p[0] || q[1] !== p[1]) && near(q) < own + 0.25) ? 30 : 0;
          const cost = hits(bx) + confusing + r * 3 + (Math.sin(ang) < -0.3 ? 0.5 : 0);
          if (!best || cost < best.cost) best = { cost, cx, cy, bx };
        }
      }
      taken.push(best.bx);
      elT.style.left = ((best.cx - x0 + PAD) / VW) * 100 + "%";
      elT.style.top = ((y1 + PAD - best.cy) / VH) * 100 + "%";
    });
  };
  placeTags();
  new ResizeObserver(placeTags).observe(svg);

  const legend = [];
  if (!preview) {
    legend.push(`<span><i class="dot hit"></i>found</span>`);
    if (match.some((m) => !(m >= 0))) legend.push(`<span><i class="dot miss"></i>missed</span>`);
    if (extras.size) legend.push(`<span><i class="dot extra"></i>extra</span>`);
  }
  if (key.curve) legend.push(`<span><i class="line"></i>the curve</span>`);
  etude.$(".pl-legend").innerHTML = legend.join("");
  const fmtPt = (p) => `\\left(${p.map((v) => String(Math.round(v * 100) / 100)).join(", ")}\\right)`;
  const rows = key.points.map((p, i) => {
    const name = key.labels[i] ? key.labels[i] + ": " : "";
    const mark = preview ? "" : match[i] >= 0 ? " ✓" : " ✗ missed";
    return `- ${name}$${fmtPt(p)}$${mark}`;
  });
  if (!preview) for (const j of extras) rows.push(`- extra: $${fmtPt(placed[j])}$ ✗ costs half a point`);
  etude.$(".pl-list").innerHTML = etude.md(rows.join("\n"));
  if (!preview) {
    const hits = match.filter((m) => m >= 0).length;
    const sc = etude.$(".pl-score");
    sc.innerHTML = `${hits} of ${key.points.length} found${extras.size ? `, ${extras.size} extra` : ""}`;
    sc.classList.add(grade.score >= 1 ? "good" : grade.score > 0 ? "near" : "far");
  }
  etude.$$(".pl-list li").forEach((li) => {
    if (/✓/.test(li.textContent)) li.classList.add("ok");
    else if (/missed/.test(li.textContent)) li.classList.add("miss");
    else if (/✗/.test(li.textContent)) li.classList.add("bad");
  });
});

grader.code:
const a = answer && typeof answer === "object" ? answer : { pattern: answer == null ? "" : String(answer), flags: "" };
const pattern = String(a.pattern ?? "");
const flags = [...new Set(String(a.flags ?? "").replace(/[^imsu]/g, ""))].join("");
const tests = [
  ...view.match.map((s) => ({ s, want: true, hidden: false })),
  ...view.reject.map((s) => ({ s, want: false, hidden: false })),
  ...key.hidden.match.map((s) => ({ s, want: true, hidden: true })),
  ...key.hidden.reject.map((s) => ({ s, want: false, hidden: true })),
];
const fail = (feedback, error) => ({ score: 0, feedback, details: { error, tests: tests.map((t) => ({ ...t, got: null })) } });
if (!pattern) return fail("No pattern.");
let re;
try {
  re = new RegExp(view.mode === "find" ? pattern : `^(?:${pattern})$`, flags);
} catch (e) {
  const why = String(e.message).replace(/^Invalid regular expression: \/[\s\S]*\/[a-z]*: /, "");
  return fail(`The pattern doesn't compile: ${why}.`, why);
}
const out = tests.map((t) => ({ ...t, got: re.test(t.s) }));
const right = out.filter((t) => t.got === t.want).length;
const show = (t) => (t.s === "" ? "the empty string" : `\`${t.s}\``);
let feedback;
if (right < out.length) {
  const wrong = out.filter((t) => t.got !== t.want);
  const list = wrong.slice(0, 4).map((t) => `${show(t)}${t.hidden ? " (hidden)" : ""} should ${t.want ? "" : "not "}match`);
  if (wrong.length > 4) list.push(`${wrong.length - 4} more`);
  feedback = `${right} of ${out.length} tests pass. Still wrong: ${list.join("; ")}.`;
}
return { score: right / out.length, feedback, details: { tests: out, right, total: out.length } };

types.prepare:
const hidden = fields.hidden && typeof fields.hidden === "object" ? fields.hidden : {};
const list = (v) => (Array.isArray(v) ? v.map(String) : []);
const h = { match: list(hidden.match), reject: list(hidden.reject) };
return {
  view: {
    prompt: fields.prompt,
    match: list(fields.match),
    reject: list(fields.reject),
    mode: fields.mode === "find" ? "find" : "full",
    flags: String(fields.flags ?? "").replace(/[^imsu]/g, ""),
    hiddenCount: h.match.length + h.reject.length,
  },
  key: { hidden: h, solution: fields.solution ?? "", explanation: fields.explanation ?? "" },
};

template.css:
.sc-eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted-foreground); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.85rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.75rem; margin: 0.25rem 0 0; }

/* Code should read literally: no fused glyphs from ligature fonts. */
#card, #card * { font-variant-ligatures: none; font-feature-settings: "liga" 0, "calt" 0; }

.rx-entry { display: flex; flex-direction: column; gap: 0.4rem; }
.rx-field {
  display: flex; align-items: flex-start; gap: 0.1rem;
  border: 1px solid var(--input); border-radius: calc(var(--radius) - 2px);
  padding: 0 0.7rem; font-family: var(--font-mono);
  transition: border-color 0.15s, box-shadow 0.15s;
}
.rx-field:focus-within { border-color: var(--ring); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring) 25%, transparent); }
.rx-field.bad { border-color: color-mix(in oklab, var(--danger) 70%, transparent); }
.rx-slash { color: var(--muted-foreground); font: 1.1rem/1.5rem var(--font-mono); padding: 0.62rem 0; user-select: none; }
.rx-field input, .rx-field textarea {
  background: transparent; border: 0; outline: 0; color: var(--foreground);
  font: 1rem/1.5rem var(--font-mono); padding: 0.62rem 0.2rem; min-width: 0; margin: 0;
}
.rx-field input:disabled, .rx-field textarea:disabled { opacity: 1; color: var(--foreground); -webkit-text-fill-color: var(--foreground); }
.rx-pattern { flex: 1; resize: none; overflow: hidden; height: 2.75rem; word-break: break-all; white-space: pre-wrap; }
.rx-flags { flex: none; width: 3.6rem; color: var(--highlight) !important; -webkit-text-fill-color: var(--highlight) !important; }
/* When the pattern wraps, the closing slash and flags sit on its last line. */
.rx-field > .rx-slash:nth-of-type(2), .rx-flags { align-self: flex-end; }
.rx-status { font-size: 0.85rem; color: var(--muted-foreground); min-height: 1.4em; }
.rx-status .err { color: var(--danger); font-family: var(--font-mono); font-size: 0.8rem; }
.rx-status .all { color: var(--success); }
.rx-status .rule { color: color-mix(in oklab, var(--muted-foreground) 80%, transparent); }

.rx-tests { display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; }
.rx-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.35rem; }
.rx-test {
  display: flex; align-items: center; gap: 0.5rem; min-height: 2.25rem;
  padding: 0.3rem 0.55rem; border: 1px solid var(--border); border-radius: calc(var(--radius) - 4px);
  font: 0.86rem/1.35 var(--font-mono); transition: border-color 0.15s, background 0.15s;
}
.rx-test code { font: inherit; white-space: pre-wrap; word-break: break-all; min-width: 0; }
.rx-mark {
  flex: none; width: 1.05rem; height: 1.05rem; border-radius: 50%;
  border: 1.5px solid color-mix(in oklab, var(--foreground) 22%, transparent);
  display: grid; place-items: center; font: 700 0.62rem/1 var(--font-sans);
  transition: background 0.15s, border-color 0.15s;
}
.rx-test.pass { border-color: color-mix(in oklab, var(--success) 45%, var(--border)); background: color-mix(in oklab, var(--success) 7%, transparent); }
.rx-test.pass .rx-mark { background: var(--success); border-color: var(--success); color: var(--background); }
.rx-test.pass .rx-mark::after { content: "✓"; }
.rx-test.fail { border-color: color-mix(in oklab, var(--danger) 45%, var(--border)); background: color-mix(in oklab, var(--danger) 7%, transparent); }
.rx-test.fail .rx-mark { background: var(--danger); border-color: var(--danger); color: var(--background); }
.rx-test.fail .rx-mark::after { content: "✕"; }
.rx-test mark.hit { background: color-mix(in oklab, var(--highlight) 26%, transparent); color: inherit; border-radius: 2px; box-shadow: inset 0 -2px 0 var(--highlight); }
.rx-test .sp { color: var(--muted-foreground); }
.rx-test .rx-empty { color: var(--muted-foreground); font-style: italic; font-family: var(--font-sans); }
.rx-note { font-size: 0.82rem; margin: -0.6rem 0 0; }
.rx-hidden-results:empty { display: none; }
.rx-hidden-results .rx-tests { margin-top: 0.25rem; }
.rx-hidden-results .sub { font-size: 0.7rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: color-mix(in oklab, var(--muted-foreground) 75%, transparent); margin-bottom: 0.35rem; }
.rx-solution { font: 0.95rem var(--font-mono); background: var(--muted); padding: 0.2em 0.5em; border-radius: 0.35em; word-break: break-all; }

/* Etude 3 look: a quiet grey eyebrow and the question in the study serif, as in the Design Lab. */
.sc-eyebrow + .prose, .sc-eyebrow + .uc-prompt .uc-ask, .sc-eyebrow + .bt-ask, .sp-title, .wk-prompt, .cm-ask { font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; font-size: 1.5rem; line-height: 1.3; letter-spacing: -0.005em; }
.sc-eyebrow + .prose code, .wk-prompt code { font-size: 0.8em; }

template.js:
const { view } = etude;
const pat = etude.$(".rx-pattern");
const flg = etude.$(".rx-flags");
const field = etude.$(".rx-field");
const status = etude.$(".rx-status");
flg.value = view.flags ?? "";

const tests = [
  ...view.match.map((s) => ({ s, want: true })),
  ...view.reject.map((s) => ({ s, want: false })),
];

// Show the string with spaces made visible and the matched span marked.
const strHtml = (s, span) => {
  if (s === "") return `<span class="rx-empty">empty string</span>`;
  const esc = (t) => etude.escape(t).replace(/ /g, `<span class="sp">·</span>`);
  if (!span || span[1] <= span[0]) return esc(s);
  return esc(s.slice(0, span[0])) + `<mark class="hit">${esc(s.slice(span[0], span[1]))}</mark>` + esc(s.slice(span[1]));
};
const row = (t, i) => `<li class="rx-test" data-i="${i}"><span class="rx-mark" aria-hidden="true"></span><code>${strHtml(t.s)}</code></li>`;
for (const kind of ["match", "reject"]) {
  etude.$(`.rx-list[data-kind="${kind}"]`).innerHTML = tests.map((t, i) => ((t.want === (kind === "match")) ? row(t, i) : "")).join("");
}
const rowEls = etude.$$(".rx-tests .rx-test");
const byIndex = Object.fromEntries(rowEls.map((li) => [li.dataset.i, li]));

const paint = (results) => {
  for (const [i, t] of tests.entries()) {
    const li = byIndex[i];
    li.classList.remove("pass", "fail");
    const r = results?.[i];
    li.querySelector("code").innerHTML = strHtml(t.s, view.mode === "find" && r?.got ? r.span : null);
    if (!r) continue;
    li.classList.add(r.got === t.want ? "pass" : "fail");
  }
};

// Matching runs in a worker so a pattern with catastrophic backtracking can't freeze the card.
const workerSrc = `onmessage = (e) => {
  const { id, pattern, flags, mode, strings } = e.data;
  let re;
  try { re = new RegExp(mode === "find" ? pattern : "^(?:" + pattern + ")$", flags); }
  catch (err) { postMessage({ id, error: String(err.message) }); return; }
  postMessage({ id, results: strings.map((s) => { re.lastIndex = 0; const m = re.exec(s); return { got: !!m, span: m ? [m.index, m.index + m[0].length] : null }; }) });
};`;
let worker = null;
const spawn = () => {
  try {
    worker = new Worker(URL.createObjectURL(new Blob([workerSrc], { type: "text/javascript" })));
  } catch {
    worker = null;
  }
};
spawn();
const runInline = (pattern, flags) => {
  let re;
  try { re = new RegExp(view.mode === "find" ? pattern : `^(?:${pattern})$`, flags); }
  catch (err) { return { error: String(err.message) }; }
  return { results: tests.map((t) => { const m = re.exec(t.s); return { got: !!m, span: m ? [m.index, m.index + m[0].length] : null }; }) };
};

const ruleText = view.mode === "find" ? "A match anywhere in the string counts." : "The whole string has to match (no need for ^ and $).";
let seq = 0;
let timer = null;
const cleanFlags = () => [...new Set(flg.value.replace(/[^imsu]/g, ""))].join("");
// Engine messages repeat the pattern ("Invalid regular expression: /x/: Unterminated group"); keep the reason.
const reason = (m) => String(m).replace(/^Invalid regular expression: \/[\s\S]*\/[a-z]*: /, "").replace(/^Invalid regular expression: /, "");
const show = (res) => {
  if (res.error) {
    field.classList.add("bad");
    status.innerHTML = `<span class="err">${etude.escape(reason(res.error))}</span>`;
    paint(null);
    return;
  }
  field.classList.remove("bad");
  paint(res.results);
  const ok = res.results.filter((r, i) => r.got === tests[i].want).length;
  status.innerHTML = (ok === tests.length
    ? `<span class="all">All ${tests.length} visible tests pass.</span>`
    : `${ok} of ${tests.length} visible tests pass.`) + ` <span class="rule">${ruleText}</span>`;
};
// The pattern box grows with its content, so a long pattern stays fully visible.
const fit = () => { pat.style.height = "auto"; pat.style.height = `${pat.scrollHeight}px`; };
const evaluate = () => {
  // A pasted newline would make the pattern unreadable; keep it on one logical line.
  if (pat.value.includes("\n")) pat.value = pat.value.replace(/\n/g, "");
  fit();
  const pattern = pat.value;
  etude.setReady(pattern.length > 0 && etude.mode === "answer");
  if (!pattern) {
    field.classList.remove("bad");
    paint(null);
    status.innerHTML = `<span class="rule">${ruleText}</span>`;
    return;
  }
  const flags = cleanFlags();
  if (!worker) return show(runInline(pattern, flags));
  const id = ++seq;
  clearTimeout(timer);
  timer = setTimeout(() => {
    if (id !== seq) return;
    worker.terminate();
    spawn();
    field.classList.add("bad");
    status.innerHTML = `<span class="err">Took too long: this pattern backtracks catastrophically.</span>`;
    paint(null);
  }, 400);
  worker.onmessage = (e) => {
    if (e.data.id !== seq) return;
    clearTimeout(timer);
    show(e.data);
  };
  worker.postMessage({ id, pattern, flags, mode: view.mode, strings: tests.map((t) => t.s) });
};

if (etude.answer && typeof etude.answer === "object") {
  pat.value = etude.answer.pattern ?? "";
  flg.value = etude.answer.flags ?? flg.value;
}
pat.addEventListener("input", evaluate);
flg.addEventListener("input", () => { flg.value = cleanFlags(); evaluate(); });
for (const el of [pat, flg]) el.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); if (pat.value) etude.submit(); }
});
evaluate();
etude.getAnswer(() => ({ pattern: pat.value, flags: cleanFlags() }));

etude.onResult(({ grade, key, answer }) => {
  pat.disabled = flg.disabled = true;
  if (answer && typeof answer === "object") { pat.value = answer.pattern ?? ""; flg.value = answer.flags ?? ""; }
  fit();
  const details = grade?.details;
  if (details?.tests) {
    paint(details.tests.slice(0, tests.length).map((t) => ({ got: t.got, span: null })));
    if (details.error) {
      field.classList.add("bad");
      status.innerHTML = `<span class="err">${etude.escape(reason(details.error))}</span>`;
    } else {
      status.textContent = `${details.right} of ${details.total} tests pass, hidden ones included.`;
    }
  } else if (!pat.value) status.textContent = "";
  const hidden = details?.tests ? details.tests.slice(tests.length) : [
    ...key.hidden.match.map((s) => ({ s, want: true, got: null })),
    ...key.hidden.reject.map((s) => ({ s, want: false, got: null })),
  ];
  if (!hidden.length) return;
  const li = (t) => `<li class="rx-test ${t.got == null ? "" : t.got === t.want ? "pass" : "fail"}"><span class="rx-mark" aria-hidden="true"></span><code>${strHtml(t.s)}</code></li>`;
  const col = (want, title) => {
    const items = hidden.filter((t) => t.want === want);
    return items.length ? `<div><div class="sub">${title}</div><ul class="rx-list">${items.map(li).join("")}</ul></div>` : "<div></div>";
  };
  etude.$(".rx-hidden-results").innerHTML = `<div class="e-section-title">Hidden tests</div><div class="rx-tests">${col(true, "Should match")}${col(false, "Should not match")}</div>`;
});

grader.code:
const given = Array.isArray(answer?.answers) ? answer.answers : [];
const rows = given.map((g, i) => {
  const text = String(g ?? "").trim();
  const n = text === "" ? NaN : Number(text.replace(/[−–]/g, "-").replace(/,/g, ""));
  return { q: view.problems[i], given: text, want: key.answers[i], ok: n === key.answers[i] };
}).filter((r) => r.q !== undefined);
const correct = rows.filter((r) => r.ok).length;
const answered = rows.filter((r) => r.given !== "").length;
const score = Math.min(1, correct / view.target);
// The card already shows the tally; feedback only says what stood between this round and the target.
const misses = rows.filter((r) => !r.ok && r.given !== "").length;
let feedback;
if (correct < view.target) {
  const short = view.target - correct;
  feedback = misses
    ? `${short} short of the target. ${misses} of your ${answered} answers were wrong: accuracy matters as much as speed.`
    : `${short} short of the target: every answer was right, so it's speed that needs work.`;
}
return { score, feedback, details: { rows, correct, answered } };

types.prepare:
const seconds = Math.min(120, Math.max(10, Math.round(Number(fields.seconds) || 30)));
const target = Math.max(1, Math.round(Number(fields.target) || 12));
const mode = ["sums", "times", "percent", "mixed"].includes(fields.mode) ? fields.mode : "mixed";
const make = {
  sums() {
    if (rng.bool(0.6)) { const a = rng.int(12, 89), b = rng.int(11, 99 - a > 11 ? 99 - a : 11); return [`${a} + ${b}`, a + b]; }
    const a = rng.int(31, 99), b = rng.int(11, a - 5); return [`${a} − ${b}`, a - b];
  },
  times() { const a = rng.int(3, 12), b = rng.int(3, 12); return [`${a} × ${b}`, a * b]; },
  percent() {
    const p = rng.pick([10, 20, 25, 50, 75, 5, 30, 40]);
    // Bases that keep the answer a whole number.
    const step = { 10: 10, 20: 5, 25: 4, 50: 2, 75: 4, 5: 20, 30: 10, 40: 5 }[p];
    const n = step * rng.int(2, Math.floor(400 / step));
    return [`${p}% of ${n}`, (p * n) / 100];
  },
};
// Enough problems that nobody runs out: about one per second.
const count = seconds + 10;
const problems = [], answers = [];
// No repeats inside a round (times tables only have so many, so give up after enough tries).
const seen = new Set();
let tries = 0;
while (problems.length < count) {
  const kind = mode === "mixed" ? rng.pick(["sums", "sums", "times", "times", "percent"]) : mode;
  const [q, a] = make[kind]();
  if (seen.has(q) && tries++ < 400) continue;
  seen.add(q);
  problems.push(q);
  answers.push(a);
}
return {
  view: { seconds, target, mode, problems, note: fields.note ?? "" },
  key: { answers },
};

types.demo:
// An example round for watch mode: a few more right answers than the target, and one slip.
const n = Math.min((key.answers ?? []).length, Number(view.target) + 2);
const answers = (key.answers ?? []).slice(0, n).map(String);
if (n > 4) answers[Math.floor(n / 2)] = String(Number(answers[Math.floor(n / 2)]) + 1);
return { answers };

