// A soft piano voice: a handful of harmonics, a quick hammer attack and a two-stage decay.
// The AudioContext is created on the first gesture inside the frame (browsers require one).
const Piano = (() => {
  let ctx = null, out = null, wave = null, noise = null;
  const setup = (c, dest) => {
    const comp = c.createDynamicsCompressor();
    comp.threshold.value = -18; comp.knee.value = 14; comp.ratio.value = 3;
    comp.attack.value = 0.003; comp.release.value = 0.3;
    const g = c.createGain();
    g.gain.value = 0.7;
    g.connect(comp); comp.connect(dest);
    const amps = [0, 1, 0.45, 0.28, 0.17, 0.1, 0.06, 0.035, 0.02, 0.012];
    const w = c.createPeriodicWave(new Float32Array(amps.length), Float32Array.from(amps));
    const n = c.createBuffer(1, Math.ceil(c.sampleRate * 0.04), c.sampleRate);
    const d = n.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length);
    return { out: g, wave: w, noise: n };
  };
  const get = () => {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    if (!ctx) {
      ctx = new AC();
      ({ out, wave, noise } = setup(ctx, ctx.destination));
    }
    if (ctx.state === "suspended") ctx.resume();
    return ctx;
  };
  const voice = (c, dest, w, nz, midi, t, len, vel) => {
    const f = 440 * 2 ** ((midi - 69) / 12);
    const ring = Math.max(0.6, 2.8 - (midi - 48) * 0.045); // low notes ring longer
    const peak = 0.2 * vel;
    const env = c.createGain();
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(peak, t + 0.005);
    env.gain.setTargetAtTime(peak * 0.4, t + 0.005, 0.08);
    env.gain.setTargetAtTime(0.0001, t + 0.2, ring / 4);
    const stop = t + Math.min(len ?? ring, ring) ;
    env.gain.setTargetAtTime(0.0001, stop, 0.09);
    const lp = c.createBiquadFilter();
    lp.type = "lowpass"; lp.Q.value = 0.5;
    lp.frequency.setValueAtTime(Math.min(f * 10, 15000), t);
    lp.frequency.setTargetAtTime(Math.min(f * 3.2, 8000), t + 0.01, 0.3);
    lp.connect(env); env.connect(dest);
    [[0, 1], [5, 0.55], [-4, 0.35]].forEach(([cents, a]) => {
      const o = c.createOscillator();
      o.setPeriodicWave(w); o.frequency.value = f; o.detune.value = cents;
      const g = c.createGain(); g.gain.value = a;
      o.connect(g); g.connect(lp);
      o.start(t); o.stop(stop + 0.6);
    });
    const h = c.createBufferSource(); h.buffer = nz;
    const bp = c.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = Math.min(f * 4, 6000); bp.Q.value = 1.2;
    const hg = c.createGain(); hg.gain.value = 0.05 * vel;
    h.connect(bp); bp.connect(hg); hg.connect(dest);
    h.start(t);
  };
  return {
    /** notes: [{ m: midi, at: seconds from now, len?: seconds, vel?: 0..1 }]. Returns the total length. */
    play(notes) {
      const c = get();
      if (!c) return 0;
      const t0 = c.currentTime + 0.04;
      let end = 0;
      for (const n of notes) {
        voice(c, out, wave, noise, n.m, t0 + (n.at ?? 0), n.len, n.vel ?? 0.8);
        end = Math.max(end, (n.at ?? 0) + (n.len ?? 1.2));
      }
      return end;
    },
    /** Renders notes offline (for checking the sound without speakers). */
    async render(notes, seconds = 3) {
      const c = new OfflineAudioContext(1, Math.ceil(44100 * seconds), 44100);
      const s = setup(c, c.destination);
      for (const n of notes) voice(c, s.out, s.wave, s.noise, n.m, n.at ?? 0, n.len, n.vel ?? 0.8);
      return c.startRendering();
    },
  };
})();

const PLAY_ICON = `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13a1 1 0 0 0 1.5.86l10.5-6.5a1 1 0 0 0 0-1.72L9.5 4.64A1 1 0 0 0 8 5.5Z" fill="currentColor"/></svg>`;

// Piano keyboard drawn one octave (C to B) per SVG, so narrow screens can stack octaves.
// keyboard(host, { lo, octaves, wrap, labels, onPress }) returns { el(midi), all(), set(midi, cls, on), label(midi, text) }.
function keyboard(host, { lo = 48, octaves = 2, wrap = true, labels = "c", onPress = null } = {}) {
  const W = 24, H = 104, BW = 14.5, BH = 66, R = 3;
  const WHITE = [0, 2, 4, 5, 7, 9, 11];
  const BLACK = { 1: [1, -0.12], 3: [2, 0.12], 6: [4, -0.16], 8: [5, 0], 10: [6, 0.16] }; // pc -> [boundary, offset]
  const LETTER = { 0: "C", 2: "D", 4: "E", 5: "F", 7: "G", 9: "A", 11: "B" };
  const SPOKEN = ["C", "C♯", "D", "E♭", "E", "F", "F♯", "G", "A♭", "A", "B♭", "B"];
  const aria = (m) => `role="button" aria-label="${SPOKEN[m % 12]}${Math.floor(m / 12) - 1}"`;
  const whitePath = (x) => `M${x + 0.5} 0.5H${x + W - 0.5}V${H - R - 0.5}Q${x + W - 0.5} ${H - 0.5} ${x + W - R - 0.5} ${H - 0.5}H${x + R + 0.5}Q${x + 0.5} ${H - 0.5} ${x + 0.5} ${H - R - 0.5}Z`;
  host.classList.add("kb");
  if (!wrap) host.classList.add("kb-nowrap");
  let html = "";
  for (let k = 0; k < octaves; k++) {
    const base = lo + 12 * k;
    let s = `<svg class="kb-oct" viewBox="0 0 ${7 * W} ${H}" role="group" aria-label="Octave ${Math.floor(base / 12) - 1}">`;
    WHITE.forEach((pc, i) => {
      const m = base + pc, x = i * W;
      const text = labels === "all" ? LETTER[pc] : labels === "c" && pc === 0 ? `C${Math.floor(m / 12) - 1}` : "";
      s += `<g class="key white" data-m="${m}" ${aria(m)}><path d="${whitePath(x)}"/><text x="${x + W / 2}" y="${H - 9}" class="kl">${text}</text></g>`;
    });
    for (const [pc, [b, off]] of Object.entries(BLACK)) {
      const m = base + Number(pc), x = (b + off) * W - BW / 2;
      s += `<g class="key black" data-m="${m}" ${aria(m)}><path d="M${x} 0H${x + BW}V${BH - 2}Q${x + BW} ${BH} ${x + BW - 2} ${BH}H${x + 2}Q${x} ${BH} ${x} ${BH - 2}Z"/><text x="${x + BW / 2}" y="${BH - 7}" class="kl"></text></g>`;
    }
    html += s + "</svg>";
  }
  host.innerHTML = html;
  const map = new Map([...host.querySelectorAll(".key")].map((g) => [Number(g.dataset.m), g]));
  if (onPress) {
    host.addEventListener("pointerdown", (e) => {
      const g = e.target.closest?.(".key");
      if (!g || e.button > 0) return;
      e.preventDefault();
      g.classList.add("down");
      setTimeout(() => g.classList.remove("down"), 160);
      onPress(Number(g.dataset.m));
    });
  }
  return {
    el: (m) => map.get(m),
    all: () => [...map.keys()],
    set(m, cls, on = true) { map.get(m)?.classList.toggle(cls, on); },
    clear(cls) { for (const g of map.values()) g.classList.remove(cls); },
    label(m, text) { const t = map.get(m)?.querySelector("text"); if (t) t.textContent = text; },
  };
}

// Spelled note names: { letter: "E", acc: -1, oct: 4 } -> "E♭4", or KaTeX "\mathrm{E}\flat_{4}".
const ACC = { "-2": "𝄫", "-1": "♭", 0: "", 1: "♯", 2: "𝄪" };
const ACC_TEX = { "-2": "\\flat\\flat", "-1": "\\flat", 0: "", 1: "\\sharp", 2: "\\sharp\\sharp" };
const noteText = (n) => `${n.letter}${ACC[n.acc]}${n.oct ?? ""}`;
const noteTex = (n) => `\\mathrm{${n.letter}}${ACC_TEX[n.acc]}${n.oct != null ? `_{${n.oct}}` : ""}`;

// Clefs and accidentals traced from Noto Music (OFL); 1000 units per em, 250 per staff space, origin on the bottom line.
const GLYPH = {"gclef": "M314 801Q300 854 291 906Q282 958 282 1012Q282 1059 288 1100Q295 1142 307 1177Q320 1217 341 1252Q362 1288 386 1311Q409 1334 427 1334Q451 1334 493 1249Q514 1206 524 1156Q534 1106 534 1049Q534 978 515 908Q496 837 460 775Q423 713 372 666L407 498Q422 500 432 501Q442 502 447 502Q508 502 556 468Q604 433 632 377Q661 321 661 254Q661 177 622 116Q582 54 503 25Q508 8 532 -117Q538 -147 541 -164Q544 -182 545 -195Q546 -208 546 -225Q546 -275 522 -314Q497 -354 456 -376Q414 -398 363 -398Q311 -398 271 -378Q231 -359 208 -324Q185 -290 185 -245Q185 -197 212 -165Q238 -133 287 -133Q329 -133 356 -164Q382 -194 382 -236Q382 -272 357 -299Q332 -326 292 -326H282Q308 -365 364 -365Q433 -365 472 -320Q511 -275 511 -205Q511 -188 507 -160Q503 -131 493 -91Q483 -51 478 -25Q472 1 470 12Q436 2 390 2Q304 2 222 52Q142 102 96 184Q50 266 50 361Q50 451 91 530Q132 609 192 675Q253 741 314 801ZM341 826Q364 838 390 870Q416 903 440 945Q464 987 479 1030Q494 1072 494 1106Q494 1142 483 1163Q472 1184 445 1184Q421 1184 398 1162Q376 1140 358 1104Q341 1067 331 1022Q321 977 321 930Q321 898 328 872Q334 846 341 826ZM398 379Q371 373 347 354Q323 334 308 306Q294 279 294 248Q294 223 307 196Q320 170 339 154Q352 142 365 136Q380 129 380 123Q380 120 370 117Q332 126 302 151Q271 176 254 212Q236 247 236 287Q236 330 254 370Q271 410 302 442Q334 474 374 490L345 641Q229 547 174 456Q120 366 120 277Q120 212 154 156Q188 100 247 66Q306 31 380 31Q400 31 420 35Q441 39 464 45ZM495 55Q593 97 593 227Q593 270 571 306Q549 341 512 362Q475 383 429 383Z", "fclef": "M50 123Q216 231 288 301Q336 348 373 408Q410 469 432 536Q453 603 453 669Q453 728 435 774Q417 819 383 845Q349 871 302 871Q284 871 264 867Q245 863 224 855Q181 839 158 814Q135 788 135 765Q135 756 143 752Q151 748 158 748Q168 748 183 752Q190 754 196 755Q203 756 210 756Q248 756 272 734Q296 711 296 674Q296 638 266 612Q236 586 195 586Q146 586 111 617Q76 648 76 697Q76 756 109 802Q142 848 198 874Q255 900 324 900Q400 900 460 867Q520 834 556 776Q591 719 591 646Q591 551 538 464Q511 419 476 379Q442 339 389 298Q336 256 256 208Q176 160 57 101ZM687 809Q710 809 726 793Q742 777 742 754Q742 731 726 716Q710 700 687 700Q664 700 648 716Q632 731 632 754Q632 777 648 793Q664 809 687 809ZM687 589Q710 589 726 573Q742 557 742 534Q742 511 726 496Q710 480 687 480Q664 480 648 496Q632 511 632 534Q632 557 648 573Q664 589 687 589Z", "sharp": "M97 46V189L50 177V277L97 290V486H128V298L195 314V509H226V322L275 333V234L226 220V77L275 89V-14L226 -26V-214H195V-34L128 -52V-247H97V-59L50 -71V32ZM195 70V214L128 197V54Z", "flat": "M50 615H81V225Q118 262 165 262Q197 262 223 240Q249 219 249 178Q249 146 230 119Q211 92 179 65L110 6Q91 -10 76 -26Q61 -41 50 -55ZM81 12Q107 40 125 64Q143 87 153 105Q164 124 170 140Q175 156 175 170Q175 198 162 210Q149 223 134 223Q118 223 102 212Q87 200 81 180Z"};
const { view } = etude;
// Staff geometry in SVG units: a space is 10, position p (0 = bottom line, 8 = top line) sits at y = B - 5p.
const B = 100, SP = 10, SC = SP / 250, X0 = 4, W = 168;
const yOf = (p) => B - 5 * p;
const glyph = (d, x, y, cls = "") => `<path class="${cls}" transform="translate(${x} ${y}) scale(${SC} ${-SC})" d="${d}"/>`;

const draw = (noteCls = "") => {
  let s = "";
  for (let i = 0; i < 5; i++) s += `<line class="sl" x1="${X0}" x2="${X0 + W}" y1="${yOf(2 * i)}" y2="${yOf(2 * i)}"/>`;
  // The treble clef's curl wraps the G line; the bass clef's dots straddle the F line.
  s += view.clef === "treble" ? glyph(GLYPH.gclef, X0 + 3, B, "clef") : glyph(GLYPH.fclef, X0 + 4, B - 105 * SC, "clef");
  const nx = X0 + 104, p = view.pos;
  for (let q = -2; q >= p; q -= 2) s += `<line class="ledger" x1="${nx - 11}" x2="${nx + 11}" y1="${yOf(q)}" y2="${yOf(q)}"/>`;
  for (let q = 10; q <= p; q += 2) s += `<line class="ledger" x1="${nx - 11}" x2="${nx + 11}" y1="${yOf(q)}" y2="${yOf(q)}"/>`;
  const y = yOf(p);
  let n = "";
  if (view.acc === 1) n += glyph(GLYPH.sharp, nx - 22, y + 134 * SC);
  if (view.acc === -1) n += glyph(GLYPH.flat, nx - 20, y + 105 * SC);
  // Quarter note: stem up below the middle line, down from it.
  const up = p < 4;
  n += `<ellipse cx="${nx}" cy="${y}" rx="6.1" ry="4.3" transform="rotate(-20 ${nx} ${y})"/>`;
  n += up ? `<line class="stem" x1="${nx + 5.6}" x2="${nx + 5.6}" y1="${y - 1.2}" y2="${y - 35}"/>` : `<line class="stem" x1="${nx - 5.6}" x2="${nx - 5.6}" y1="${y + 1.2}" y2="${y + 35}"/>`;
  s += `<g class="note ${noteCls}">${n}</g>`;
  // Fit the drawing: staff plus whatever ledger lines and stem stick out.
  const top = Math.min(yOf(8) - 22, y - 42), bot = Math.max(yOf(0) + 20, y + 42);
  etude.$(".st-staff").innerHTML = `<svg viewBox="0 ${top} ${W + 2 * X0} ${bot - top}" role="img" aria-label="A note on a ${view.clef} staff">${s}</svg>`;
};
draw();

let picked = Number.isInteger(etude.answer) ? etude.answer : null;
const LET_PC = { c: 0, d: 2, e: 4, f: 5, g: 7, a: 9, b: 11 };
const LO = 60;
const kb = keyboard(etude.$(".st-kb"), {
  lo: LO, octaves: 1, labels: "all", wrap: false,
  onPress: (m) => choose(m, true),
});
const choose = (m, sound) => {
  if (etude.mode !== "answer") return;
  picked = m;
  kb.clear("sel");
  kb.set(m, "sel");
  if (sound) Piano.play([{ m, len: 0.9 }]);
  etude.setReady(true);
};
etude.$(".st-help").innerHTML = view.accidentals
  ? "Tap a key, or press <kbd>A</kbd>–<kbd>G</kbd> for the white keys."
  : "Tap a key, or press <kbd>A</kbd>–<kbd>G</kbd>.";
window.addEventListener("keydown", (e) => {
  if (etude.mode !== "answer" || e.ctrlKey || e.metaKey || e.altKey) return;
  const pc = LET_PC[e.key.toLowerCase()];
  if (pc !== undefined) { e.preventDefault(); choose(LO + pc, true); }
});
etude.setReady(false);
if (picked !== null) choose(picked, false);
etude.getAnswer(() => picked);

etude.onResult(({ key, answer, grade }) => {
  const ok = grade?.score >= 1;
  const attempted = Number.isInteger(answer);
  etude.$(".st-kb").classList.add("static");
  kb.clear("sel");
  const target = LO + key.pc;
  if (attempted && !ok) kb.set(LO + (((answer % 12) + 12) % 12), "bad");
  kb.set(target, attempted ? (ok ? "ok" : "miss") : "ok");
  draw(attempted && ok ? "ok" : "");
  etude.$(".st-answer").innerHTML = etude.md(`The note is $${key.tex}$${key.midi === 60 ? " (middle C)" : ""}.`);
  const b = etude.$(".st-play");
  b.querySelector(".ic").innerHTML = PLAY_ICON;
  b.addEventListener("click", () => Piano.play([{ m: key.midi, len: 1.4 }]));
});

grader.code:
const guess = answer && typeof answer === "object" ? answer : {};
const ids = view.chips.map((c) => c.id);
const placed = ids.filter((id) => Number.isFinite(guess[id]));
if (!placed.length) return { score: 0, feedback: "Nothing placed." };
const span = view.to - view.from;
const tol = key.tolerance;
// Closeness: full within the tolerance, falling to 0 at a fifth of the timeline away.
const close = (id) => {
  if (!Number.isFinite(guess[id])) return 0;
  const off = Math.abs(guess[id] - key.years[id]);
  return off <= tol ? 1 : Math.max(0, 1 - (off - tol) / (span / 5));
};
// Order: the longest run of placed events already in true order.
const byGuess = placed.slice().sort((a, b) => guess[a] - guess[b]);
const order = std.lis(byGuess.map((id) => key.years[id])) / ids.length;
const closeness = ids.reduce((s, id) => s + close(id), 0) / ids.length;
const score = Math.round((0.5 * order + 0.5 * closeness) * 100) / 100;
const off = Object.fromEntries(ids.map((id) => [id, Number.isFinite(guess[id]) ? Math.round(guess[id] - key.years[id]) : null]));
const worst = ids.filter((id) => off[id] !== null).sort((a, b) => Math.abs(off[b]) - Math.abs(off[a]))[0];
let feedback;
if (score < 1) {
  const parts = [];
  if (placed.length < ids.length) parts.push(`${ids.length - placed.length} not placed`);
  if (order < placed.length / ids.length) parts.push("some are out of order");
  const far = ids.filter((id) => off[id] !== null && Math.abs(off[id]) > tol).length;
  if (worst && Math.abs(off[worst]) > tol) parts.push(`${far > 1 ? `${far} events are more than ${tol} years off; the furthest, ` : ""}${view.chips.find((c) => c.id === worst).label}, is ${Math.abs(off[worst])} years ${off[worst] > 0 ? "too late" : "too early"}`);
  feedback = parts.length ? parts.join("; ").replace(/^./, (ch) => ch.toUpperCase()) + "." : undefined;
}
return { score, feedback, details: { off } };

types.prepare:
const all = (Array.isArray(fields.events) ? fields.events : []).filter((e) => e && typeof e.label === "string" && Number.isFinite(e.year));
const n = Math.max(3, Math.min(6, Math.round(Number(fields.count) || 5), all.length));
// Pick n events whose years differ, so the order is always well defined.
const picked = [];
for (const e of rng.shuffle(all)) {
  if (picked.length >= n) break;
  if (!picked.some((p) => p.year === e.year)) picked.push(e);
}
const ys = all.map((e) => e.year);
let [from, to] = Array.isArray(fields.range) && fields.range.length === 2 ? fields.range.map(Number) : [Math.min(...ys), Math.max(...ys)];
if (!(Array.isArray(fields.range) && fields.range.length === 2)) {
  const pad = Math.max(3, Math.round((to - from) * 0.06));
  from -= pad; to += pad;
}
const chips = picked.map((e, i) => ({ id: "e" + i, label: e.label }));
return {
  view: { prompt: fields.prompt ?? "", from, to, chips, anchors: Array.isArray(fields.anchors) ? fields.anchors : [] },
  key: { years: Object.fromEntries(picked.map((e, i) => ["e" + i, e.year])), notes: Object.fromEntries(picked.map((e, i) => ["e" + i, e.note ?? ""])), tolerance: Number(fields.tolerance ?? 3), explanation: fields.explanation ?? "" },
};

template.css:
.sc-eyebrow { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted-foreground); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.8rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.7rem; margin: 0.25rem 0 0; }

.tl-prompt { font-size: 1.05rem; }
.tl-prompt, .tl-tray, .tl-wrap, .tl-help { user-select: none; -webkit-user-select: none; }

/* The tray: events still to place. */
.tl-tray { display: flex; flex-wrap: wrap; gap: 0.4rem; min-height: 2.9rem; padding: 0.45rem; border-radius: calc(var(--radius) - 2px); background: color-mix(in oklab, var(--foreground) 3%, transparent); border: 1px dashed transparent; transition: border-color 0.15s, background 0.15s; }
.tl-tray-empty { display: none; align-self: center; padding: 0 0.35rem; font-size: 0.8rem; color: var(--muted-foreground); }
.tl-tray.empty .tl-tray-empty { display: block; }
.tl-tray.drop { border-color: var(--highlight); background: color-mix(in oklab, var(--highlight) 7%, transparent); }
body[data-mode="result"] .tl-tray.empty { display: none; }

/* The line. .tl is exactly the axis; the wrap's padding lets end cards hang past it. */
.tl-wrap { padding: 0 1rem; }
.tl { position: relative; --axis: 80px; font-variant-numeric: tabular-nums; transition: height 0.25s cubic-bezier(0.22, 1, 0.36, 1); }
.tl-axis { position: absolute; left: -0.35rem; right: -0.35rem; top: var(--axis); height: 1px; margin-top: -0.5px; background: color-mix(in oklab, var(--foreground) 55%, transparent); }
.tl-ticks i { position: absolute; top: var(--axis); width: 1px; height: 3px; margin-left: -0.5px; background: color-mix(in oklab, var(--foreground) 28%, transparent); }
.tl-ticks i.major { height: 6px; background: color-mix(in oklab, var(--foreground) 55%, transparent); }
.tl-ticks { position: absolute; inset: 0; z-index: 3; pointer-events: none; }
.tl-ticks span { position: absolute; top: var(--lab, 9px); left: 0; transform: translateX(-50%); padding: 1px 4px; background: var(--background); font: 500 0.72rem/1 var(--font-sans); letter-spacing: 0.02em; color: var(--muted-foreground); white-space: nowrap; }
.tl-hint { position: absolute; left: 0; right: 0; top: calc(var(--axis) - 2.1rem); text-align: center; font-size: 0.78rem; color: color-mix(in oklab, var(--muted-foreground) 70%, transparent); pointer-events: none; }
.tl.targeting .tl-hint { visibility: hidden; }

/* Stems from each card to its year, and a dot on the axis. */
.tl-stems { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
.tl-stems i { position: absolute; width: 1px; margin-left: -0.5px; background: color-mix(in oklab, var(--foreground) 30%, transparent); }
.tl-stems i.h { width: auto; height: 1px; margin: -0.5px 0 0; }
.tl-stems b { position: absolute; z-index: 3; top: var(--axis); width: 7px; height: 7px; margin: -3.5px 0 0 -3.5px; border-radius: 50%; background: var(--highlight); box-shadow: 0 0 0 2px var(--background); }
.tl-stems b.anchor { background: var(--muted-foreground); width: 5px; height: 5px; margin: -2.5px 0 0 -2.5px; border-radius: 0; transform: rotate(45deg); }
.tl-stems i.tl-ok { background: color-mix(in oklab, var(--success) 45%, transparent); }
.tl-stems b.tl-ok { background: var(--success); }
.tl-stems i.tl-bad { background: color-mix(in oklab, var(--danger) 40%, transparent); }
.tl-stems b.tl-bad { background: var(--danger); }
.tl-stems b.tl-miss { background: var(--muted-foreground); width: 5px; height: 5px; margin: -2.5px 0 0 -2.5px; }

/* An event chip. In the tray it's a small tag; on the line it gains its year. */
.tl-chip {
  --tx: 0px; --ty: 0px;
  display: inline-flex; align-items: center; gap: 0.45rem; max-width: 22rem;
  min-height: 2.05rem; padding: 0.25rem 0.65rem 0.25rem 0.5rem;
  border-radius: 0.45rem; border: 1px solid color-mix(in oklab, var(--foreground) 15%, transparent);
  background: var(--card, var(--background)); color: var(--foreground);
  font: 500 0.82rem/1.25 var(--font-sans); text-align: left;
  cursor: grab; touch-action: none; user-select: none; -webkit-user-select: none; -webkit-tap-highlight-color: transparent;
  transform: translate(var(--tx), var(--ty));
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
@media (pointer: coarse) { .tl-tray .tl-chip { min-height: 2.35rem; } }
.tl-chip .grip { flex: none; width: 5px; height: 9px; fill: color-mix(in oklab, var(--muted-foreground) 65%, transparent); }
.tl-chip .lbl { overflow-wrap: anywhere; }
.tl-chip .yr { display: none; }
.tl-chip:hover { border-color: color-mix(in oklab, var(--highlight) 50%, transparent); }
.tl-chip:focus-visible { outline: none; border-color: var(--highlight); box-shadow: 0 0 0 3px color-mix(in oklab, var(--highlight) 22%, transparent); }
.tl-chip.dragging { cursor: grabbing; z-index: 30 !important; border-color: var(--highlight); box-shadow: 0 8px 22px rgb(0 0 0 / 0.25); transition: none; }

/* On the line: a compact label with its year under it. */
.tl-pins .tl-chip, .tl-anchor { position: absolute; z-index: 4; }
.tl-pins .tl-chip { width: max-content; flex-direction: column; align-items: flex-start; gap: 0.08rem; min-height: 0; max-width: 10.5rem; padding: 0.22rem 0.5rem 0.26rem; border-radius: 0.38rem; font-size: 0.74rem; line-height: 1.22; }
.tl-pins .tl-chip .grip { display: none; }
.tl-pins .tl-chip .yr { display: block; font: 600 0.68rem/1.15 var(--font-sans); letter-spacing: 0.02em; color: var(--highlight); }
.tl-anchor { width: max-content; display: flex; flex-direction: column; align-items: flex-start; gap: 0.08rem; max-width: 8.6rem; padding: 0.22rem 0.5rem 0.26rem; border-radius: 0.38rem; border: 1px dashed color-mix(in oklab, var(--foreground) 22%, transparent); font-size: 0.74rem; line-height: 1.22; color: color-mix(in oklab, var(--foreground) 80%, transparent); pointer-events: none; }
.tl-anchor .yr { font: 600 0.68rem/1.15 var(--font-sans); letter-spacing: 0.02em; color: var(--muted-foreground); }
.tl-anchor .yr::after { content: " · given"; font-weight: 400; }

/* While dragging: a guide down to the axis with the year it would land on. */
.tl-guide { position: absolute; top: 0; height: var(--axis); width: 0; border-left: 1px dashed var(--highlight); pointer-events: none; z-index: 6; }
.tl-guide span { position: absolute; z-index: 5; top: var(--axis); left: 0; transform: translate(-50%, 6px); padding: 0.1rem 0.42rem; border-radius: 0.3rem; background: var(--highlight); color: var(--background); font: 600 0.72rem/1.3 var(--font-sans); white-space: nowrap; }

/* Result: the chip stays where you put it; colour only on the dot, the border and the year. */
.tl-chip:disabled { cursor: default; opacity: 1; }
.tl-pins .tl-chip.tl-ok { border-color: color-mix(in oklab, var(--success) 50%, transparent); }
.tl-pins .tl-chip.tl-ok .yr { color: var(--foreground); }
.tl-chip .yr .ck { font-style: normal; color: var(--success); margin-left: 0.3em; }
.tl-pins .tl-chip.tl-bad { border-color: color-mix(in oklab, var(--danger) 45%, transparent); }
.tl-pins .tl-chip.tl-bad .yr { color: var(--foreground); }
.tl-pins .tl-chip.tl-miss { border-style: dashed; border-color: color-mix(in oklab, var(--foreground) 30%, transparent); color: var(--muted-foreground); }
.tl-pins .tl-chip.tl-miss .yr { color: var(--foreground); }
.tl-chip .yr s { color: color-mix(in oklab, var(--danger) 70%, var(--muted-foreground)); text-decoration-thickness: 1px; font-weight: 400; margin-left: 0.5em; }
.tl-chip .yr em { font-style: normal; }
.tl-chip.tl-ok .yr em { color: var(--muted-foreground); font-weight: 500; margin-left: 0.4em; }
.tl-chip.tl-miss .yr em { font-weight: 400; color: var(--muted-foreground); margin-left: 0.4em; }
.tl.is-preview .tl-pins .tl-chip .yr { color: var(--foreground); }

/* Where a wrong one belongs: a hollow ring at the true year and a thin arc to it from your year. */
.tl-marks { position: absolute; left: 0; top: 0; z-index: 3; pointer-events: none; overflow: visible; }
.tl-marks path { fill: none; stroke: color-mix(in oklab, var(--danger) 80%, var(--muted-foreground)); stroke-width: 1.35; stroke-linecap: round; }
.tl-marks path.head { fill: color-mix(in oklab, var(--danger) 80%, var(--muted-foreground)); stroke: none; }
.tl-marks circle { fill: var(--background); stroke: color-mix(in oklab, var(--danger) 80%, var(--muted-foreground)); stroke-width: 1.35; }
/* On grading, a misplaced chip slides to its true year. */
body[data-mode="result"] .tl-pins .tl-chip { transition: left 0.6s cubic-bezier(0.22, 1, 0.36, 1), top 0.6s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.2s; }

.tl-help { font-size: 0.8rem; margin: -0.25rem 0 0; }
@media (pointer: coarse) { .tl-help .kb { display: none; } }

/* The reveal: every event in order. */
.tl-list { display: flex; flex-direction: column; }
.tl-row { display: grid; grid-template-columns: 3.2rem 1fr auto; gap: 0.75rem; align-items: baseline; padding: 0.45rem 0; font-size: 0.9rem; border-top: 1px solid color-mix(in oklab, var(--border) 70%, transparent); }
.tl-list .e-section-title + .tl-row { border-top-color: color-mix(in oklab, var(--foreground) 35%, transparent); }
.tl-row b { font-weight: 600; font-variant-numeric: tabular-nums; }
.tl-row .lbl { display: flex; flex-direction: column; }
.tl-row .nt { font-size: 0.8rem; color: var(--muted-foreground); }
.tl-row .st { font-size: 0.8rem; white-space: nowrap; font-variant-numeric: tabular-nums; color: var(--muted-foreground); }
.tl-row .st.ok::before { content: "✓ "; color: var(--success); }
.tl-row .st.bad { color: color-mix(in oklab, var(--danger) 80%, var(--foreground)); }

@media (max-width: 480px) {
  .tl-wrap { padding: 0 0.6rem; }
  .tl-chip { font-size: 0.8rem; }
  .tl-pins .tl-chip, .tl-anchor { max-width: 6.6rem; font-size: 0.7rem; padding: 0.2rem 0.42rem 0.24rem; }
  .tl-pins .tl-chip .yr, .tl-anchor .yr { font-size: 0.66rem; }
  .tl-anchor .yr::after { content: ""; }
  .tl-ticks span { font-size: 0.64rem; }
  .tl-row { grid-template-columns: 2.9rem 1fr; row-gap: 0.05rem; }
  .tl-row .st { grid-column: 2; }
}

/* Cards are flags: the stem meets a square corner on the side nearest the axis. */
.tl-pins [data-side="up"][data-dir="r"] { border-bottom-left-radius: 0; }
.tl-pins [data-side="up"][data-dir="l"] { border-bottom-right-radius: 0; }
.tl-pins [data-side="down"][data-dir="r"] { border-top-left-radius: 0; }
.tl-pins [data-side="down"][data-dir="l"] { border-top-right-radius: 0; }

/* Etude 3 look: a quiet grey eyebrow and the question in the study serif, as in the Design Lab. */
.sc-eyebrow + .prose, .sc-eyebrow + .uc-prompt .uc-ask, .sc-eyebrow + .bt-ask, .sp-title, .wk-prompt, .cm-ask { font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; font-size: 1.5rem; line-height: 1.3; letter-spacing: -0.005em; }
.sc-eyebrow + .prose code, .wk-prompt code { font-size: 0.8em; }

template.js:
const { view } = etude;
const { from, to } = view;
const tl = etude.$(".tl"), tray = etude.$(".tl-tray"), wrap = etude.$(".tl-wrap");
const span = to - from;
const fmt = (y) => (y < 0 ? `${-y} BC` : String(y));
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

tl.setAttribute("role", "group");
tl.setAttribute("aria-label", `Timeline from ${fmt(from)} to ${fmt(to)}`);
tl.innerHTML = `<div class="tl-hint">Drop events on the line</div><div class="tl-ticks"></div><div class="tl-axis"></div><div class="tl-stems"></div><div class="tl-marks"></div><div class="tl-pins"></div><div class="tl-guide" hidden><span></span></div>`;
const ticksEl = tl.querySelector(".tl-ticks"), stemsEl = tl.querySelector(".tl-stems"), pins = tl.querySelector(".tl-pins");
const marksEl = tl.querySelector(".tl-marks"), guide = tl.querySelector(".tl-guide"), hint = tl.querySelector(".tl-hint");

const guess = {};
if (etude.answer && typeof etude.answer === "object") for (const [k, v] of Object.entries(etude.answer)) if (Number.isFinite(v)) guess[k] = v;
let result = null; // { key, given } once graded

const GRIP = `<svg class="grip" viewBox="0 0 6 10" aria-hidden="true"><circle cx="1" cy="1" r="1"/><circle cx="5" cy="1" r="1"/><circle cx="1" cy="5" r="1"/><circle cx="5" cy="5" r="1"/><circle cx="1" cy="9" r="1"/><circle cx="5" cy="9" r="1"/></svg>`;
const chipEl = {};
for (const c of view.chips) {
  const el = document.createElement("button");
  el.type = "button";
  el.className = "tl-chip";
  el.dataset.id = c.id;
  el.innerHTML = `${GRIP}<span class="lbl">${etude.escape(c.label)}</span><span class="yr"></span>`;
  chipEl[c.id] = el;
}
const anchorEl = view.anchors
  .filter((a) => a && Number.isFinite(a.year) && a.year >= from && a.year <= to)
  .map((a) => {
    const el = document.createElement("div");
    el.className = "tl-anchor";
    el.innerHTML = `<span class="lbl">${etude.escape(a.label)}</span><span class="yr">${fmt(a.year)}</span>`;
    el.title = `${a.label} (${fmt(a.year)}), given`;
    pins.appendChild(el);
    return { el, year: a.year };
  });

// Geometry, in px inside .tl. The axis runs the full width of .tl; .tl-wrap's padding is room
// for cards near the ends to hang over without leaving the card.
const STEM = 12, GAP = 7, LABEL_H = 22;
let geo = { w: 600, axisY: 80 };
let arcs = { runs: [], band: 0 }; // result only: where each wrong one was put
const xOf = (y) => ((y - from) / span) * geo.w;
const yearAt = (clientX) => {
  const r = tl.getBoundingClientRect();
  return Math.round(from + clamp((clientX - r.left) / r.width, 0, 1) * span);
};

// Ticks: labels at a round step that leaves room for them, minor ticks between.
function ticks(w) {
  const steps = [1, 2, 5, 10, 20, 25, 50, 100, 200, 250, 500, 1000, 2000, 5000];
  const major = steps.find((s) => (w / span) * s >= 64) ?? 5000;
  // Minor ticks on round years (every 1, 5, 10, 25… years), at most five per labelled step.
  const minor = [1, 2, 5, 10, 25, 50, 100, 250, 500, 1000].find((m) => major % m === 0 && m < major && major / m <= 5 && (w / span) * m >= 9) ?? major;
  const out = [];
  for (let y = Math.ceil(from / minor) * minor; y <= to; y += minor) out.push({ y, major: y % major === 0 });
  return out;
}

// Once graded every event sits at its true year; where you put it is drawn as a ghost on the axis.
const attemptMade = () => result && result.given !== result.key.years;
const placedYear = (id) => (result ? result.key.years[id] : guess[id]);

function layout() {
  const w = tl.clientWidth || 600;
  const pad = parseFloat(getComputedStyle(wrap).paddingLeft) || 0;
  geo.w = w;
  const ids = view.chips.map((c) => c.id).filter((id) => Number.isFinite(placedYear(id)));
  for (const c of view.chips) if (!ids.includes(c.id) && chipEl[c.id].parentNode !== tray) tray.appendChild(chipEl[c.id]);
  for (const id of ids) {
    const el = chipEl[id];
    if (el.parentNode !== pins) pins.appendChild(el);
    if (!result) el.querySelector(".yr").textContent = fmt(guess[id]);
  }
  // Every card on the line, anchors included, is a flag: its stem rises from the axis at its year
  // and meets the card's left edge (or right edge near the end of the line). Each card takes the
  // lane nearest the axis, on either side, where it overlaps nothing, no nearer card stands over
  // its stem, and it stands over no farther card's stem, so stems are straight and never pass
  // behind a card.
const all = [
    ...anchorEl.map((a) => ({ el: a.el, year: a.year, anchor: true })),
    ...ids.map((id) => ({ el: chipEl[id], year: placedYear(id), id })),
  ];
  for (const it of all) { it.wd = it.el.offsetWidth; it.h = it.el.offsetHeight; it.x = xOf(it.year); }
  if (result) arcs = planArcs();
  const M = 5;
  const spanFor = (it, dir) =>
    dir === "r" ? [it.x - 0.5, it.x - 0.5 + it.wd] : dir === "l" ? [it.x + 0.5 - it.wd, it.x + 0.5] : (() => { const c = clamp(it.x, it.wd / 2 - pad, w + pad - it.wd / 2); return [c - it.wd / 2, c + it.wd / 2]; })();
  // Graded, a card below the axis must not drop its stem through a miss's hairline.
  const clearOfMisses = (x) => !arcs.runs.some((r) => x > Math.min(r.gx, r.tx) - 6 && x < Math.max(r.gx, r.tx) + 6);
  const sides = result && attemptMade() ? ["up", "down"] : null;
  function plan(order) {
    const placed = [];
    const lanes = { up: [], down: [] };
    const ok = (it, side, L, lo, hi) =>
      (side === "up" || !result || clearOfMisses(it.x)) &&
      placed.every((p) => p.side !== side ||
        (p.lane === L ? hi + GAP <= p.lo || p.hi + GAP <= lo
          : p.lane < L ? !(it.x > p.lo - M && it.x < p.hi + M)
          : !(p.x > lo - M && p.x < hi + M)));
    const loose = (it, side, L, lo, hi) => (side === "up" || !result || clearOfMisses(it.x)) && placed.every((p) => p.side !== side || p.lane !== L || hi + GAP <= p.lo || p.hi + GAP <= lo);
    let prev = "down", bad = 0;
    for (const src of order) {
      const it = { ...src };
      const dirs = [];
      if (it.x - 0.5 + it.wd <= w + pad) dirs.push("r");
      if (it.x + 0.5 - it.wd >= -pad) dirs.push("l");
      if (!dirs.length) dirs.push("c");
      const sideOrder = sides ?? (prev === "up" ? ["down", "up"] : ["up", "down"]);
      let best = null;
      const any = (it, side, L, lo, hi) => placed.every((p) => p.side !== side || p.lane !== L || hi + GAP <= p.lo || p.hi + GAP <= lo);
      for (const test of [ok, loose, any]) {
        for (let L = 0; L < 10 && !best; L++)
          for (const side of sideOrder) {
            if (best) break;
            for (const dir of dirs) {
              const [lo, hi] = spanFor(it, dir);
              if (test(it, side, L, lo, hi)) { best = { side, lane: L, dir, lo, hi }; break; }
            }
          }
        if (best) break;
        bad++;
      }
      Object.assign(it, best);
      placed.push(it);
      for (let L = 0; L <= it.lane; L++) lanes[it.side][L] ??= { h: 0 };
      lanes[it.side][it.lane].h = Math.max(lanes[it.side][it.lane].h, it.h);
      prev = it.side;
    }
    const height = [...lanes.up, ...lanes.down].reduce((s, l) => s + (l.h ? l.h + GAP : 0), 0);
    return { placed, lanes, cost: bad * 10000 + height };
  }
  // A few orders (latest first, earliest first, widest first, middle out); keep the tidiest.
  const byYear = all.slice().sort((a, b) => b.year - a.year || (a.anchor ? 1 : -1));
  const mid = (from + to) / 2;
  const orders = [byYear, byYear.slice().reverse(), all.slice().sort((a, b) => b.wd - a.wd), all.slice().sort((a, b) => Math.abs(a.year - mid) - Math.abs(b.year - mid))];
  const { placed: items, lanes } = orders.map(plan).reduce((a, b) => (b.cost < a.cost ? b : a));
  // Lane offsets from the axis; at least one lane each side keeps the band steady while placing.
  const minH = 40;
  const size = (l) => (l.h ? l.h + GAP : 0);
  const offs = (side) => {
    let acc = 0;
    return lanes[side].map((l) => { const o = acc; acc += size(l); return o; });
  };
  const up = offs("up"), down = offs("down");
  const upH = Math.max(minH + GAP, lanes.up.reduce((s, l) => s + size(l), 0));
  const downH = Math.max(minH + GAP, lanes.down.reduce((s, l) => s + size(l), 0));
  const axisY = STEM + upH;
  geo.axisY = axisY;
  const LABELS = LABEL_H + arcs.band;
  tl.style.height = `${axisY + LABELS + 6 + downH}px`;
  tl.style.setProperty("--axis", `${axisY}px`);
  tl.style.setProperty("--lab", `${9 + arcs.band}px`);
  // Year labels under the axis, knocked out of any stem passing behind them; a label a stem would
  // split down the middle is left out.
  // Stems of cards below the axis cross the label row: a label they'd cut through is left out.
  const downX = items.filter((it) => it.side === "down").map((it) => it.x);
  const labels = [];
  ticksEl.innerHTML = ticks(w)
    .map((t) => {
      const x = xOf(t.y);
      const show = t.major;
      if (show) labels.push(x);
      return `<i class="${t.major ? "major" : ""}" style="left:${x}px">${show ? `<span>${fmt(t.y)}</span>` : ""}</i>`;
    })
    .join("");
  const cls = (it) => (it.anchor ? "anchor" : [...it.el.classList].filter((k) => /^tl-(ok|bad|miss)$/.test(k)).join(" "));
  let stems = "";
  for (const it of items) {
    const top = it.side === "up" ? axisY - STEM - up[it.lane] - it.h : axisY + LABELS + 6 + down[it.lane];
    it.el.style.left = `${it.lo}px`;
    it.el.style.top = `${top}px`;
    it.el.dataset.side = it.side;
    it.el.dataset.dir = it.dir;
    const near = it.side === "up" ? top + it.h : top;
    stems += `<i class="${cls(it)}" style="left:${it.x}px;top:${Math.min(axisY, near)}px;height:${Math.abs(near - axisY)}px"></i>`;
  }
  // Dots sit on the axis at each card's year.
  stems += items.map((it) => `<b class="${cls(it)}" style="left:${it.x}px"></b>`).join("");
  stemsEl.innerHTML = stems;
  hint.hidden = ids.length > 0 || !!result;
  tray.classList.toggle("empty", !view.chips.some((c) => chipEl[c.id].parentNode === tray));
  if (result) drawMarks();
  etude.setReady(etude.mode === "answer" && ids.length > 0);
}

// ---------------------------------------------------------------- dragging
// The chip moves with a transform only and lands (lanes redone) on release: re-parenting a chip
// mid-drag would drop its pointer capture, which ends touch drags early.
let drag = null;
const inside = (r, e, pad = 0) => e.clientX > r.left - pad && e.clientX < r.right + pad && e.clientY > r.top - pad && e.clientY < r.bottom + pad;
const overLine = (e) => { const r = tl.getBoundingClientRect(); return e.clientY > r.top - 24 && e.clientY < r.bottom + 24 && e.clientX > r.left - 40 && e.clientX < r.right + 40; };
etude.root.addEventListener("pointerdown", (e) => {
  const el = e.target.closest(".tl-chip");
  if (!el || etude.mode !== "answer" || e.button > 0) return;
  e.preventDefault();
  const r = el.getBoundingClientRect();
  getSelection()?.removeAllRanges();
  drag = { el, id: el.dataset.id, dx: e.clientX - (r.left + r.width / 2), x0: e.clientX, y0: e.clientY, moved: false, year: null, toTray: false };
  el.setPointerCapture?.(e.pointerId);
});
window.addEventListener("pointermove", (e) => {
  if (!drag) return;
  if (!drag.moved && Math.hypot(e.clientX - drag.x0, e.clientY - drag.y0) < 4) return;
  drag.moved = true;
  const el = drag.el;
  el.classList.add("dragging");
  el.style.setProperty("--tx", `${e.clientX - drag.x0}px`);
  el.style.setProperty("--ty", `${e.clientY - drag.y0}px`);
  drag.toTray = Number.isFinite(guess[drag.id]) && inside(tray.getBoundingClientRect(), e, 8);
  tray.classList.toggle("drop", drag.toTray);
  drag.year = !drag.toTray && overLine(e) ? yearAt(e.clientX - drag.dx) : null;
  guide.hidden = drag.year === null;
  tl.classList.toggle("targeting", drag.year !== null);
  if (drag.year !== null) {
    guide.style.left = `${xOf(drag.year)}px`;
    guide.firstChild.textContent = fmt(drag.year);
    el.querySelector(".yr").textContent = fmt(drag.year);
  } else el.querySelector(".yr").textContent = Number.isFinite(guess[drag.id]) ? fmt(guess[drag.id]) : "";
});
const end = () => {
  if (!drag) return;
  const { el, id } = drag;
  getSelection()?.removeAllRanges();
  el.classList.remove("dragging");
  el.style.removeProperty("--tx");
  el.style.removeProperty("--ty");
  tray.classList.remove("drop");
  tl.classList.remove("targeting");
  guide.hidden = true;
  if (drag.toTray) delete guess[id];
  else if (drag.year !== null) guess[id] = drag.year;
  // A tap on a chip in the tray drops it in the middle of the line.
  else if (!drag.moved && !Number.isFinite(guess[id])) guess[id] = Math.round((from + to) / 2);
  drag = null;
  layout();
};
window.addEventListener("pointerup", end);
window.addEventListener("pointercancel", end);
etude.root.addEventListener("keydown", (e) => {
  const el = e.target.closest?.(".tl-chip");
  if (!el || etude.mode !== "answer" || e.ctrlKey || e.metaKey || e.altKey) return;
  const id = el.dataset.id;
  if ((e.key === "Delete" || e.key === "Backspace") && Number.isFinite(guess[id])) {
    e.preventDefault();
    delete guess[id];
  } else if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
    e.preventDefault();
    const d = (e.key === "ArrowRight" ? 1 : -1) * (e.shiftKey ? 10 : 1);
    guess[id] = clamp((Number.isFinite(guess[id]) ? guess[id] : Math.round((from + to) / 2)) + d, from, to);
  } else return;
  layout();
  el.focus({ preventScroll: true });
});
let lastW = 0;
new ResizeObserver(() => { if (tl.clientWidth !== lastW) { lastW = tl.clientWidth; layout(); } }).observe(tl);
document.fonts?.ready.then(layout);
layout();
etude.getAnswer(() => ({ ...guess }));

// ---------------------------------------------------------------- result
// A wrong one: a small hollow ghost on the axis where you put it, and a thin arc under the axis
// from it to the true year, where the event now sits. Arcs that overlap nest one level deeper.
function planArcs() {
  const { key, given } = result;
  const runs = [];
  for (const c of view.chips) {
    const y = key.years[c.id], g = given[c.id];
    if (!Number.isFinite(g) || Math.abs(g - y) <= key.tolerance) continue;
    runs.push({ id: c.id, gx: xOf(g), tx: xOf(y) });
  }
  // Each miss is a straight hairline on its own track under the axis; overlapping ones take
  // separate tracks, so lines are parallel and never cross.
  runs.sort((p, q) => Math.min(p.gx, p.tx) - Math.min(q.gx, q.tx));
  const ends = [];
  for (const r of runs) {
    const a = Math.min(r.gx, r.tx) - 8, b = Math.max(r.gx, r.tx) + 8;
    let t = ends.findIndex((e) => e < a);
    if (t < 0) t = ends.length;
    ends[t] = b;
    r.depth = 9 + t * 7;
  }
  return { runs, band: runs.length ? Math.max(...runs.map((r) => r.depth)) + 5 : 0 };
}
function drawMarks() {
  const y0 = geo.axisY;
  let svg = "";
  for (const r of arcs.runs) {
    const y = y0 + r.depth, dir = Math.sign(r.tx - r.gx);
    svg += `<path d="M${r.gx + dir * 3} ${y}L${r.tx - dir * 4} ${y}"/>`;
    svg += `<path class="head" d="M${r.tx} ${y}L${r.tx - dir * 5} ${y - 2.6}L${r.tx - dir * 5} ${y + 2.6}Z"/>`;
    svg += `<circle cx="${r.gx}" cy="${y}" r="2.5"/>`;
  }
  marksEl.innerHTML = `<svg width="${geo.w}" height="${tl.offsetHeight}" viewBox="0 0 ${geo.w} ${tl.offsetHeight}" aria-hidden="true">${svg}</svg>`;
  tl.classList.toggle("has-arcs", arcs.runs.length > 0);
}

etude.onResult(({ key, answer }) => {
  const given = answer && typeof answer === "object" ? answer : {};
  const attempt = Object.keys(given).length > 0;
  const tol = key.tolerance;
  // A preview with no attempt shows every event at its true year.
  result = { key, given: attempt ? given : key.years };
  for (const c of view.chips) {
    const el = chipEl[c.id];
    el.disabled = true;
    el.querySelector(".grip")?.remove();
    const y = key.years[c.id], g = given[c.id];
    const yr = el.querySelector(".yr");
    if (!attempt) { yr.textContent = fmt(y); continue; }
    if (!Number.isFinite(g)) {
      el.classList.add("tl-miss");
      yr.innerHTML = `${fmt(y)}<em>not placed</em>`;
    } else if (Math.abs(g - y) <= tol) {
      el.classList.add("tl-ok");
      yr.innerHTML = g === y ? `${fmt(y)}<i class="ck">✓</i>` : `${fmt(y)}<i class="ck">✓</i><em>yours ${fmt(g)}</em>`;
    } else {
      el.classList.add("tl-bad");
      yr.innerHTML = `${fmt(y)}<s aria-label="you put ${fmt(g)}">${fmt(g)}</s>`;
      el.title = `${c.label}: ${fmt(y)}; you put ${fmt(g)}`;
    }
  }
  if (!attempt) tl.classList.add("is-preview");
  layout();
  // The line already reads in order; a list only adds something when events carry notes.
  if (!view.chips.some((c) => key.notes?.[c.id])) return;
  const rows = view.chips
    .slice()
    .sort((a, b) => key.years[a.id] - key.years[b.id])
    .map((c) => `<div class="tl-row"><b>${fmt(key.years[c.id])}</b><span class="lbl">${etude.escape(c.label)}${key.notes?.[c.id] ? `<span class="nt">${etude.mdInline(key.notes[c.id])}</span>` : ""}</span></div>`)
    .join("");
  etude.$(".tl-list").innerHTML = `<div class="e-section-title">In order</div>${rows}`;
});

grader.code:
const words = Array.isArray(view.words) ? view.words.map(String) : [];
const typed = (Array.isArray(answer?.typed) ? answer.typed : []).slice(0, words.length).map((s) => String(s ?? ""));
while (typed.length && typed[typed.length - 1] === "") typed.pop();
const ms = Math.min(3600000, Math.max(0, Number(answer?.ms) || 0));
const complete = answer?.complete === true;
const history = (Array.isArray(answer?.history) ? answer.history : [])
  .slice(0, 900)
  .filter((h) => Array.isArray(h) && h.length >= 4 && h.slice(0, 4).every((x) => Number.isFinite(Number(x))))
  .map((h) => h.slice(0, 4).map(Number));
if (!typed.length || ms < 300) {
  return { score: 0, feedback: "Nothing was typed.", details: { wpm: 0, raw: 0, acc: 0, correct: 0, incorrect: 0, extra: 0, missed: 0, consistency: null, ms, history: [], typed: [], complete } };
}
const last = typed.length - 1;
// Without `complete`, the last word was still being typed when the clock stopped.
let correct = 0, incorrect = 0, extra = 0, missed = 0, wordChars = 0, spaces = 0;
typed.forEach((t, i) => {
  const w = Array.from(words[i]), a = Array.from(t);
  const partial = i === last && !complete;
  for (let j = 0; j < Math.max(w.length, a.length); j++) {
    if (j >= w.length) extra++;
    else if (j >= a.length) { if (!partial) missed++; }
    else if (a[j] === w[j]) correct++;
    else incorrect++;
  }
  if (t === words[i]) { wordChars += w.length; if (i < last) spaces++; }
  else if (partial && words[i].startsWith(t)) wordChars += a.length;
});
const min = ms / 60000;
// Monkeytype's definitions: a word is 5 characters; WPM counts only correctly typed words and the spaces after them.
const wpm = (wordChars + spaces) / 5 / min;
const raw = (correct + incorrect + extra + last) / 5 / min;
const k = answer?.keys;
const kc = Number(k?.correct), ki = Number(k?.incorrect);
const acc = Number.isFinite(kc) && Number.isFinite(ki) && kc + ki > 0
  ? (100 * kc) / (kc + ki)
  : (100 * correct) / Math.max(1, correct + incorrect + extra);
// Consistency: how steady the per-second raw speed was (Monkeytype's kogasa of the coefficient of variation).
let consistency = null;
const raws = history.map((h) => h[2]);
if (raws.length >= 2) {
  const mean = raws.reduce((s, x) => s + x, 0) / raws.length;
  const sd = Math.sqrt(raws.reduce((s, x) => s + (x - mean) ** 2, 0) / raws.length);
  const cov = mean > 0 ? sd / mean : 1;
  consistency = 100 * (1 - Math.tanh(cov + cov ** 3 / 3 + cov ** 5 / 5));
}
const r2 = (x) => Math.round(x * 100) / 100;
const target = Number(view.target) || 60;
const score = Math.min(1, wpm / target);
let feedback;
if (wpm < target) {
  feedback = `${Math.ceil(target - wpm)} WPM short of ${target}.`;
  if (acc < 94) feedback += ` Accuracy was ${Math.round(acc)}%: a wrong word counts for nothing, so a little less speed would score more.`;
}
return {
  score,
  feedback,
  details: { wpm: r2(wpm), raw: r2(raw), acc: r2(acc), correct, incorrect, extra, missed, consistency: consistency === null ? null : r2(consistency), ms, history, typed, complete },
};

types.prepare:
// The 200 most common English words, the classic typing-test list.
const COMMON = "the be of and a to in he have it that for they with as not on she at by this we you do but from or which one would all will there say who make when can more if no man out other so what time up go about than into could state only new year some take come these know see use get like then first any work now may such give over think most even find day also after way many must look before great back through long where much should well people down own just because good each those feel seem how high too place little world very still nation hand old life tell write become here show house both between need mean call develop under last right move thing general school never same another begin while number part turn real leave might want point form off child few small since against ask late home interest large person end open public follow during present without again hold govern around possible head consider word program problem however lead system set order eye plan run keep face fact group play stand increase early course change help line".split(" ");
const seconds = Number(fields.seconds) > 0 ? Math.min(120, Math.max(10, Math.round(Number(fields.seconds)))) : 0;
const target = Math.max(1, Math.round(Number(fields.target) || 60));
const note = fields.note ?? "";
const text = String(fields.text ?? "").trim();
if (text) {
  const words = text.split(/\s+/).slice(0, 500);
  return { view: { words, seconds, target, note, kind: "text" }, key: {} };
}
const own = Array.isArray(fields.wordlist) ? fields.wordlist : String(fields.wordlist ?? "").split(/[\n,]/);
const pool = own.map((w) => String(w).trim()).filter(Boolean).map((w) => w.replace(/\s+/g, "_"));
const from = pool.length ? pool : COMMON;
// A timed test needs more words than anyone can type in the time: 4 a second is 240 WPM.
const count = seconds ? Math.min(500, seconds * 4) : Math.min(200, Math.max(5, Math.round(Number(fields.count) || 25)));
const words = [];
while (words.length < count) {
  const w = rng.pick(from);
  // No word twice in a row (unless the list has only one).
  if (from.length > 1 && w === words[words.length - 1]) continue;
  words.push(w);
}
return { view: { words, seconds, target, note, kind: pool.length ? "list" : "common" }, key: {} };

types.demo:
// An example test for watch mode: a steady typist around 70 WPM with a couple of slips.
const words = (view.words ?? []).map(String);
const wpm = 64 + rng.int(0, 14);
const cps = (wpm * 5) / 60;
const limit = view.seconds ? view.seconds * 1000 : Infinity;
const typed = [];
let chars = 0;
for (const w of words) {
  const c = w.length + (typed.length ? 1 : 0);
  if (((chars + c) / cps) * 1000 > limit) break;
  typed.push(w);
  chars += c;
}
const ms = view.seconds ? limit : Math.round((chars / cps) * 1000);
const history = [];
for (let s = 1; s <= Math.ceil(ms / 1000); s++) {
  const w = wpm * (0.86 + 0.14 * Math.min(1, s / 4)) + (rng.next() - 0.5) * 8;
  history.push([s, Math.round(w * 100) / 100, Math.round((w * 1.05 + (rng.next() - 0.5) * 16) * 100) / 100, rng.bool(0.15) ? 1 : 0]);
}
return { typed, ms, complete: !view.seconds, keys: { correct: chars, incorrect: rng.int(1, 3) }, history };

