const { view } = etude;
const svg = etude.$(".uc-svg");
const NS = "http://www.w3.org/2000/svg";
const el = (tag, attrs) => {
  const n = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
  return n;
};
const tex = (s) => etude.mdInline("$" + s + "$");

etude.$(".uc-theta").innerHTML = tex("\\theta = " + view.thetaTex);

// Tick marks every 15°, longer on the axes and the 30°/45° families.
const ticks = etude.$(".uc-ticks");
for (let d = 0; d < 360; d += 15) {
  const a = (d * Math.PI) / 180;
  const len = d % 90 === 0 ? 0.09 : d % 45 === 0 || d % 30 === 0 ? 0.06 : 0.035;
  const c = Math.cos(a), s = -Math.sin(a);
  ticks.append(el("line", { x1: c * (1 - len), y1: s * (1 - len), x2: c * (1 + len), y2: s * (1 + len), class: d % 90 === 0 ? "major" : "" }));
}

// Axis labels as HTML so they get KaTeX.
const labels = etude.$(".uc-labels");
const place = (x, y, html, cls = "") => {
  const span = document.createElement("span");
  span.className = "uc-label " + cls;
  span.style.left = ((x + 1.4) / 2.8) * 100 + "%";
  span.style.top = ((y + 1.4) / 2.8) * 100 + "%";
  span.innerHTML = html;
  labels.append(span);
  return span;
};
place(1.3, 0.12, tex("x"));
place(-0.1, -1.3, tex("y"));
place(1.08, 0.12, tex("1"), "small");

let deg = null;
const mine = etude.$(".uc-mine");
const draw = () => {
  mine.style.display = deg === null ? "none" : "";
  if (deg === null) return;
  const a = (deg * Math.PI) / 180;
  const x = Math.cos(a), y = -Math.sin(a);
  mine.querySelector(".uc-ray").setAttribute("x2", x);
  mine.querySelector(".uc-ray").setAttribute("y2", y);
  for (const c of mine.querySelectorAll("circle")) c.setAttribute("cx", x), c.setAttribute("cy", y);
  svg.setAttribute("aria-valuenow", deg);
  svg.setAttribute("aria-valuetext", deg + " degrees");
};
const set = (d) => {
  if (etude.mode !== "answer") return;
  deg = ((Math.round(d / 15) * 15) % 360 + 360) % 360;
  draw();
  etude.setReady(true);
};

const angleAt = (e) => {
  const pt = svg.createSVGPoint();
  pt.x = e.clientX;
  pt.y = e.clientY;
  const p = pt.matrixTransform(svg.getScreenCTM().inverse());
  if (Math.hypot(p.x, p.y) < 0.12) return null; // the centre has no direction
  return (Math.atan2(-p.y, p.x) * 180) / Math.PI;
};
let dragging = false;
svg.addEventListener("pointerdown", (e) => {
  if (etude.mode !== "answer") return;
  const a = angleAt(e);
  if (a === null) return;
  dragging = true;
  svg.setPointerCapture(e.pointerId);
  svg.classList.add("dragging");
  set(a);
  e.preventDefault();
});
svg.addEventListener("pointermove", (e) => {
  if (!dragging) return;
  const a = angleAt(e);
  if (a !== null) set(a);
});
const end = () => { dragging = false; svg.classList.remove("dragging"); };
svg.addEventListener("pointerup", end);
svg.addEventListener("pointercancel", end);

window.addEventListener("keydown", (e) => {
  if (etude.mode !== "answer" || e.ctrlKey || e.metaKey || e.altKey) return;
  const step = { ArrowLeft: 15, ArrowUp: 15, ArrowRight: -15, ArrowDown: -15 }[e.key];
  if (step === undefined) return;
  e.preventDefault();
  set((deg ?? 0) + (deg === null ? 0 : step));
});

if (etude.answer && Number.isFinite(Number(etude.answer.deg))) set(Number(etude.answer.deg));
else etude.setReady(false);
draw();
etude.getAnswer(() => (deg === null ? null : { deg }));

const gcd = (p, q) => (q ? gcd(q, p % q) : p);
const radOf = (d) => {
  const k = d / 15;
  if (!k) return "0";
  const g = gcd(k, 12), n = k / g, m = 12 / g;
  const top = n === 1 ? "\\pi" : n + "\\pi";
  return m === 1 ? top : `\\frac{${top}}{${m}}`;
};

etude.onResult(({ grade, key, answer }) => {
  svg.classList.add("done");
  if (answer && Number.isFinite(Number(answer.deg))) {
    deg = ((Math.round(Number(answer.deg) / 15) * 15) % 360 + 360) % 360;
    draw();
  }
  const preview = document.body.dataset.preview === "1";
  const score = grade?.score;
  if (deg !== null && !preview) mine.classList.add(score >= 1 ? "right" : score > 0 ? "near" : "wrong");
  if (score >= 1 || preview) mine.style.display = "none";

  // The arc from 0 to θ, spiralling outward when θ goes past a full turn.
  const truth = etude.$(".uc-truth");
  const D = key.degrees;
  const turns = Math.abs(D) / 360;
  const pts = [];
  const n = Math.max(2, Math.ceil(Math.abs(D) / 4));
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const a = ((D * t) * Math.PI) / 180;
    const r = 0.3 + (turns > 1 ? 0.13 * t * turns : 0);
    pts.push([r * Math.cos(a), -r * Math.sin(a)]);
  }
  if (Math.abs(D) > 0) {
    truth.append(el("polyline", { points: pts.map((p) => p.join(",")).join(" "), class: "uc-arc" }));
    const [ex, ey] = pts[pts.length - 1];
    const [px, py] = pts[pts.length - 2];
    // Aim the head along the last few samples so it follows the curve.
    const [qx, qy] = pts[Math.max(0, pts.length - 4)];
    const ang = Math.atan2(ey - qy, ex - qx);
    const h = 0.1;
    truth.append(el("path", {
      d: `M${ex},${ey} L${ex - h * Math.cos(ang - 0.5)},${ey - h * Math.sin(ang - 0.5)} L${ex - h * Math.cos(ang + 0.5)},${ey - h * Math.sin(ang + 0.5)} Z`,
      class: "uc-arrow",
    }));
  }
  const a = (key.target * Math.PI) / 180;
  const x = Math.cos(a), y = -Math.sin(a);
  truth.append(el("line", { x1: x, y1: 0, x2: x, y2: y, class: "uc-drop" }));
  truth.append(el("line", { x1: 0, y1: 0, x2: x, y2: y, class: "uc-truth-ray" }));
  truth.append(el("circle", { cx: x, cy: y, r: 0.065, class: "uc-truth-dot" }));

  // Your ray goes under the correct one.
  svg.insertBefore(mine, truth);

  // Coordinates near the point, in the nearest spot outside the circle that clears the axes and labels.
  const lab = place(0, 0, tex(key.coordsTex), "coords");
  const stage = etude.$(".uc-stage");
  const leader = el("line", { class: "uc-leader" });
  truth.prepend(leader);
  const fit = () => {
    const W = stage.clientWidth;
    const u = W / 2.8; // px per unit
    const c = 1.4 * u; // centre, px
    const px = c + x * u, py = c + y * u;
    const w = lab.offsetWidth, h = lab.offsetHeight;
    const busy = [...labels.querySelectorAll(".uc-label:not(.coords)")].map((n) => {
      const r = n.getBoundingClientRect(), s = stage.getBoundingClientRect();
      return [r.left - s.left - 4, r.top - s.top - 4, r.right - s.left + 4, r.bottom - s.top + 4];
    });
    const clear = (l, t) => {
      const r = l + w, b = t + h;
      if (l < 2 || t < 2 || r > W - 2 || b > W - 2) return false;
      // nearest point of the box to the centre must be outside the circle
      const nx = Math.max(l, Math.min(c, r)), ny = Math.max(t, Math.min(c, b));
      if (Math.hypot(nx - c, ny - c) < u + 10) return false;
      // axes run from -1.3 to 1.3
      const ax = 1.3 * u;
      if (t < c + 3 && b > c - 3 && r > c - ax && l < c + ax) return false;
      if (l < c + 3 && r > c - 3 && b > c - ax && t < c + ax) return false;
      return !busy.some(([bl, bt, br, bb]) => l < br && r > bl && t < bb && b > bt);
    };
    let best = null;
    for (let t = 0; t <= W - h; t += 4)
      for (let l = 0; l <= W - w; l += 4) {
        if (!clear(l, t)) continue;
        const nx = Math.max(l, Math.min(px, l + w)), ny = Math.max(t, Math.min(py, t + h));
        const d = Math.hypot(nx - px, ny - py);
        if (!best || d < best.d) best = { l, t, d, nx, ny };
      }
    if (!best) {
      lab.style.display = "none";
      leader.style.display = "none";
      return;
    }
    lab.style.display = "";
    lab.style.left = best.l + w / 2 + "px";
    lab.style.top = best.t + h / 2 + "px";
    const far = best.d > 0.3 * u;
    leader.style.display = far ? "" : "none";
    if (far) {
      const toU = (v) => v / u - 1.4;
      leader.setAttribute("x1", x);
      leader.setAttribute("y1", y);
      leader.setAttribute("x2", toU(best.nx));
      leader.setAttribute("y2", toU(best.ny));
    }
  };
  fit();
  new ResizeObserver(fit).observe(stage);

  const same = key.degrees === key.target;
  const facts = [
    `$\\theta = ${view.thetaTex}${view.units === "radians" ? " = " + key.degrees + "^\\circ" : " = " + key.radTex}$`,
    same ? "" : `which lands in the same place as $${key.targetTex}$ (${key.degrees < 0 ? "negative angles turn clockwise" : "one full turn is $360^\\circ$"}).`,
  ].filter(Boolean).join(", ");
  etude.$(".uc-facts").innerHTML = etude.md(
    facts + `\n\n$(\\cos\\theta, \\sin\\theta) = ${key.coordsTex}$` +
    (deg !== null && !preview && score < 1 ? `\n\nYou placed ${view.units === "radians" ? `$${radOf(deg)}$ ($${deg}^\\circ$)` : `$${deg}^\\circ$`}: ${score > 0 ? "one $15^\\circ$ step off, half credit." : `$${grade.details?.off ?? ""}^\\circ$ off.`}` : ""),
  );
});

grader.code:
// The answer is { value, paths, h }: only the typed value is graded; the scratch work rides along.
const value = typeof answer === "string" ? answer : String(answer?.value ?? "");
const r = std.math.check(value, key.answers ?? [], { form: view.form || "any" });
return { score: r.score, feedback: r.feedback, details: { latex: r.latex } };

template.css:
.wk-pad { display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 0.75rem; }
.wk-pad[hidden] { display: none; }
.wk-tools { display: flex; align-items: center; gap: 0.35rem; }
.wk-tools .e-btn { height: 2.25rem; min-width: 2.25rem; padding: 0 0.75rem; font-size: 0.82rem; }
.wk-tools .e-btn.is-on { background: var(--accent); border-color: var(--foreground); }
.wk-tools .wk-icon { padding: 0; font-size: 1.05rem; }
.wk-gap { flex: 1; }
.wk-canvas {
  width: 100%; display: block; touch-action: none; cursor: crosshair;
  border: 1px solid var(--border); border-radius: var(--radius);
  background: color-mix(in oklab, var(--foreground) 2.5%, transparent);
}
.wk-canvas.locked { cursor: default; }
.wk-row { display: flex; gap: 0.5rem; align-items: stretch; }
.wk-input { flex: 1; min-width: 0; font-size: 1rem; }
.wk-toggle { flex: none; height: auto; white-space: nowrap; padding: 0 0.85rem; }
.wk-toggle[aria-pressed="true"] { background: var(--accent); border-color: var(--foreground); }
.wk-preview {
  margin-top: 0.5rem; min-height: 3.4rem; display: flex; align-items: center; justify-content: center;
  padding: 0.6rem 1rem; border-radius: var(--radius);
  background: color-mix(in oklab, var(--foreground) 4%, transparent);
  font-size: 1.3rem; overflow-x: auto; overflow-y: hidden;
}
.wk-empty { font-size: 0.9rem; color: var(--muted-foreground); }
.wk-preview.is-unread { opacity: 0.55; }
.wk-preview.is-correct { box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--success) 60%, transparent); background: color-mix(in oklab, var(--success) 9%, transparent); }
.wk-preview.is-wrong { box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--danger) 60%, transparent); background: color-mix(in oklab, var(--danger) 9%, transparent); }
.wk-preview.is-partial { box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--warning) 60%, transparent); background: color-mix(in oklab, var(--warning) 9%, transparent); }
.wk-note { font-size: 0.82rem; color: var(--muted-foreground); min-height: 1.2em; margin-top: 0.3rem; text-align: center; }
.wk-note.is-error { color: var(--warning); }
.wk-accepted { display: flex; flex-wrap: wrap; gap: 0.5rem 1.25rem; align-items: center; font-size: 1.15rem; }
.wk-solution .katex-display { margin: 0.4rem 0; overflow-x: auto; overflow-y: hidden; }
[data-mode="result"] .wk-row { display: none; }
@media (max-width: 520px) {
  .wk-tools .e-btn { height: 2.6rem; min-width: 2.6rem; }
}

/* Etude 3 look: a quiet grey eyebrow and the question in the study serif, as in the Design Lab. */
.sc-eyebrow + .prose, .sc-eyebrow + .uc-prompt .uc-ask, .sc-eyebrow + .bt-ask, .sp-title, .wk-prompt, .cm-ask { font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; font-size: 1.5rem; line-height: 1.3; letter-spacing: -0.005em; }
.sc-eyebrow + .prose code, .wk-prompt code { font-size: 0.8em; }

template.js:
const input = etude.$("#answer");
const preview = etude.$(".wk-preview");
const note = etude.$(".wk-note");
const pad = etude.$(".wk-pad");
const toggle = etude.$(".wk-toggle");
const canvas = etude.$(".wk-canvas");
const ctx = canvas.getContext("2d");
const { math } = etude;
input.placeholder ||= "Final answer";

// Strokes are kept in canvas-width units, so the work replays at any size.
const strokes = [];
let tool = "pen", current = null;
const ratio = 0.62;
// Work loaded from an answer replays at the width it was written at (never wider than the pad), and the
// pad shrinks to fit it.
let basis = 0, replay = false;
const scale = () => (basis ? Math.min(W(), basis) : W());
const css = () => getComputedStyle(document.documentElement);
const W = () => canvas.clientWidth, H = () => canvas.clientHeight;

function fit() {
  const w = canvas.clientWidth;
  if (!w) return;
  const dpr = window.devicePixelRatio || 1;
  // Phones get a taller pad: there is room vertically and fingers need it.
  let h = Math.round(Math.min(Math.max(w * (w < 520 ? 0.95 : ratio), 220), 440));
  if (replay && strokes.length) {
    const maxY = Math.max(...strokes.flatMap((s) => s.pts.map((p) => p[1])));
    h = Math.round(Math.max(maxY * Math.min(w, basis || w) + 28, 120));
  }
  canvas.style.height = h + "px";
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  paint();
}

function paint() {
  if (!canvas.width) return;
  const w = W(), h = H(), c = css();
  ctx.clearRect(0, 0, w, h);
  // Faint graph paper.
  ctx.strokeStyle = c.getPropertyValue("--border").trim() || "rgba(128,128,128,.2)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = 24; x < w; x += 24) { ctx.moveTo(x + 0.5, 0); ctx.lineTo(x + 0.5, h); }
  for (let y = 24; y < h; y += 24) { ctx.moveTo(0, y + 0.5); ctx.lineTo(w, y + 0.5); }
  ctx.stroke();
  const ink = c.getPropertyValue("--foreground").trim() || "#111";
  // Ink is drawn on its own pass so the eraser can't remove the grid: erased spans just aren't drawn.
  const layer = document.createElement("canvas");
  layer.width = canvas.width; layer.height = canvas.height;
  const lc = layer.getContext("2d");
  const dpr = window.devicePixelRatio || 1;
  lc.setTransform(dpr, 0, 0, dpr, 0, 0);
  for (const s of current ? [...strokes, current] : strokes) stroke(lc, s, ink, scale());
  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.drawImage(layer, 0, 0); ctx.restore();
}

function stroke(c, s, ink, w) {
  const p = s.pts;
  if (!p.length) return;
  c.lineCap = "round"; c.lineJoin = "round";
  c.globalCompositeOperation = s.erase ? "destination-out" : "source-over";
  c.strokeStyle = ink;
  c.lineWidth = s.erase ? 18 : Math.max(1.6, w * 0.0035);
  c.beginPath();
  c.moveTo(p[0][0] * w, p[0][1] * w);
  if (p.length === 1) c.lineTo(p[0][0] * w + 0.01, p[0][1] * w);
  for (let i = 1; i < p.length - 1; i++) {
    const mx = ((p[i][0] + p[i + 1][0]) / 2) * w, my = ((p[i][1] + p[i + 1][1]) / 2) * w;
    c.quadraticCurveTo(p[i][0] * w, p[i][1] * w, mx, my);
  }
  if (p.length > 1) c.lineTo(p[p.length - 1][0] * w, p[p.length - 1][1] * w);
  c.stroke();
  c.globalCompositeOperation = "source-over";
}

const at = (e) => { const r = canvas.getBoundingClientRect(), k = scale() * (r.width / (W() || 1)) || 1; return [(e.clientX - r.left) / k, (e.clientY - r.top) / k]; };
canvas.addEventListener("pointerdown", (e) => {
  if (etude.mode !== "answer") return;
  canvas.setPointerCapture(e.pointerId);
  current = { erase: tool === "eraser" || e.buttons === 32, pts: [at(e)] };
  paint();
});
canvas.addEventListener("pointermove", (e) => {
  if (!current) return;
  for (const ev of e.getCoalescedEvents?.() ?? [e]) current.pts.push(at(ev));
  paint();
});
const finish = () => { if (!current) return; strokes.push(current); current = null; paint(); };
canvas.addEventListener("pointerup", finish);
canvas.addEventListener("pointercancel", finish);

etude.$(".wk-tools").addEventListener("click", (e) => {
  const b = e.target.closest("button");
  if (!b) return;
  if (b.dataset.tool) { tool = b.dataset.tool; etude.$$("[data-tool]").forEach((x) => x.classList.toggle("is-on", x === b)); }
  if (b.dataset.act === "undo") strokes.pop();
  if (b.dataset.act === "clear") strokes.length = 0;
  paint();
});

const show = (on) => {
  pad.hidden = !on;
  toggle.setAttribute("aria-pressed", String(on));
  toggle.title = on ? "Hide the scratchpad" : "Show the scratchpad";
  if (on) requestAnimationFrame(fit);
};
toggle.addEventListener("click", () => show(pad.hidden));
new ResizeObserver(fit).observe(canvas);

// What renders is what gets graded: the parsed answer printed back as LaTeX.
const render = () => {
  const src = input.value.trim();
  preview.classList.remove("is-unread");
  note.classList.remove("is-error");
  note.textContent = "";
  if (!src) {
    preview.innerHTML = `<span class="wk-empty">Your answer renders here</span>`;
    etude.setReady(false);
    return;
  }
  try {
    preview.innerHTML = etude.tex(math.toLatex(math.parse(src)), true);
  } catch (e) {
    preview.innerHTML = etude.tex(src, true);
    preview.classList.add("is-unread");
    note.classList.add("is-error");
    note.textContent = `Can't read this yet: ${e.message}`;
  }
  etude.setReady(true);
};
input.addEventListener("input", render);
input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); etude.submit(); } });
window.addEventListener("keydown", (e) => {
  if (etude.mode !== "answer" || pad.hidden || e.target === input) return;
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") { e.preventDefault(); strokes.pop(); paint(); }
  else if (e.key === "e" || e.key === "p") etude.$(`[data-tool="${e.key === "e" ? "eraser" : "pen"}"]`).click();
});

// Rounded and capped so an attempt stays small.
const packed = () => {
  let budget = 6000;
  const paths = [];
  for (const s of strokes) {
    if (s.erase || budget <= 0) continue;
    const pts = s.pts.slice(0, budget).map(([x, y]) => [Math.round(x * 1e4) / 1e4, Math.round(y * 1e4) / 1e4]);
    budget -= pts.length;
    paths.push(pts);
  }
  return paths;
};
etude.getAnswer(() => ({ value: input.value, paths: packed(), w: Math.round(scale()) }));

function load(answer) {
  if (answer == null) return;
  input.value = typeof answer === "string" ? answer : String(answer.value ?? "");
  const paths = Array.isArray(answer?.paths) ? answer.paths : [];
  if (paths.length) {
    strokes.length = 0;
    for (const p of paths) if (Array.isArray(p) && p.length) strokes.push({ pts: p });
    basis = Number(answer.w) > 0 ? Number(answer.w) : 0;
    replay = true;
    show(true);
  }
  render();
}
load(etude.answer);
if (etude.answer == null) render();

etude.onResult(({ grade, key, answer }) => {
  input.disabled = true;
  canvas.classList.add("locked");
  if (answer != null && !strokes.length) load(answer);
  // Without scratch work there is nothing to show above the answer.
  if (!strokes.length) pad.hidden = true;
  const s = grade?.score;
  preview.classList.add(s == null ? "is-partial" : s >= 1 ? "is-correct" : s > 0 ? "is-partial" : "is-wrong");
  if (grade?.feedback) { note.classList.remove("is-error"); note.textContent = grade.feedback; }
  const shown = (a) => { try { return etude.tex(math.toLatex(math.parse(a))); } catch { return etude.tex(a); } };
  const box = etude.$(".wk-accepted");
  if (box) box.innerHTML = (key.answers ?? []).slice(0, 1).map((a) => `<span>${/\\[a-zA-Z{]/.test(a) ? etude.tex(a) : shown(a)}</span>`).join("");
});

fields.generator:
// A speed and a time that give a whole number of kilometres.
let v, t, d;
do { v = rng.int(6, 30) * 10; t = rng.pick([15, 20, 30, 40, 45, 50, 75, 90]); d = (v * t) / 60; } while (!Number.isInteger(d));
return {
  prompt: `A train covers **${d} km** in **${t} minutes**. What is its average speed?`,
  answer: v,
  explanation: `Speed is distance over time, with the time in hours: $\\frac{${d}\\,\\text{km}}{${t}/60\\,\\text{h}} = ${v}\\,\\text{km/h}$.`,
};

const n = rng.int(2, 4);
const [g, dg] = rng.pick([["\\sin x", "\\cos x"], ["\\cos x", "-\\sin x"], ["e^{x}", "e^{x}"], ["\\ln x", "\\frac{1}{x}"]]);
const xn = `x^{${n}}`, xn1 = n - 1 === 1 ? "x" : `x^{${n - 1}}`;
const d = dg.startsWith("-") ? `${n}${xn1} ${g} - ${xn} ${dg.slice(1)}` : `${n}${xn1} ${g} + ${xn} \\cdot ${dg}`;
return {
  prompt: `Differentiate $f(x) = ${xn} ${g}$.`,
  answers: [d],
  explanation: `Product rule, $(uv)' = u'v + uv'$ with $u = ${xn}$ and $v = ${g}$: $$f'(x) = ${d}$$ Any equivalent form is accepted.`,
};

const NAMES = ["methane", "ethane", "propane", "butane", "pentane", "hexane"];
const n = rng.int(1, 6);
const f = `C${n === 1 ? "" : n}H${2 * n + 2}`;
return {
  prompt: `Balance the complete combustion of **${NAMES[n - 1]}**.`,
  reactants: [f, "O2"],
  products: ["CO2", "H2O"],
  explanation: `Carbon first: ${n === 1 ? "$1$ carbon makes $1\\,\\mathrm{CO_2}$" : `$${n}$ carbons make $${n}\\,\\mathrm{CO_2}$`}. Then hydrogen: $${2 * n + 2}$ hydrogens make $${n + 1}\\,\\mathrm{H_2O}$. That's $${2 * n} + ${n + 1} = ${3 * n + 1}$ oxygen atoms on the right, so ` +
    ((3 * n + 1) % 2
      ? `$\\frac{${3 * n + 1}}{2}\\,\\mathrm{O_2}$. Half a molecule isn't allowed, so double everything: $2\\,\\mathrm{${f.replace(/(\d+)/g, "_{$1}")}} + ${3 * n + 1}\\,\\mathrm{O_2} \\to ${2 * n}\\,\\mathrm{CO_2} + ${2 * n + 2}\\,\\mathrm{H_2O}$.`
      : `$${(3 * n + 1) / 2}\\,\\mathrm{O_2}$.`),
};

const a = rng.pick([1, 1, -1, -1, 2, -2]);
const gap = Math.abs(a) === 2 ? 2 : rng.pick([2, 4]);
const vx = rng.int(-4 + gap / 2, 4 - gap / 2);
const r1 = vx - gap / 2, r2 = vx + gap / 2;
const vy = -a * (gap / 2) * (gap / 2);
// y = a x^2 + b x + c
const b = -a * (r1 + r2), c = a * r1 * r2;
const term = (k, x, first) => {
  if (k === 0) return "";
  const sign = k < 0 ? "-" : first ? "" : "+";
  const mag = Math.abs(k) === 1 && x ? "" : String(Math.abs(k));
  return `${sign} ${mag}${x}`.trim();
};
const tex = [term(a, "x^2", true), term(b, "x", false), term(c, "", false)].filter(Boolean).join(" ").replace(/\s+/g, " ").replace(/^- /, "-");
const factored = `${a === 1 ? "" : a === -1 ? "-" : a}(x ${r1 < 0 ? "+" : "-"} ${Math.abs(r1)})(x ${r2 < 0 ? "+" : "-"} ${Math.abs(r2)})`.replace(/\(x - 0\)/g, "x").replace(/\(x \+ 0\)/g, "x");
return {
  prompt: `Mark both roots and the vertex of $y = ${tex}$.`,
  points: [[r1, 0], [r2, 0], [vx, vy]],
  labels: ["root", "root", "vertex"],
  curve: `${a}*(x-(${r1}))*(x-(${r2}))`,
  explanation: `Factor it: $y = ${factored}$, so the roots are $x = ${r1}$ and $x = ${r2}$. The vertex sits halfway between them, at $x = \\frac{${r1} + ${r2 < 0 ? `(${r2})` : r2}}{2} = ${vx}$, and $y(${vx}) = ${vy}$. It's a ${a > 0 ? "minimum, since the parabola opens upward" : "maximum, since the parabola opens downward"} ($a = ${a}$).`,
};

